INSERT INTO public.curriculum_units (id,program_id,academic_level_id,code,name,unit_type,description,icon,display_order,content_language,translation_language,translation_mode,is_active,curriculum_version) SELECT id,program_id,academic_level_id,code,name,unit_type,description,icon,display_order,content_language,translation_language,translation_mode,is_active,curriculum_version FROM jsonb_populate_recordset(null::public.curriculum_units,'[{"id":"e7301030-2026-4000-8000-000000000001","program_id":"kineo-es","academic_level_id":"83040b48-7a19-46d7-a61c-5a3d2d947fb6","code":"ES1-S2-ANAT","name":"Semestre 2 · Anatomía II","unit_type":"subject","description":"Socle complementario de revisión: 50 preguntas originales corregidas. Consulta también el curso y las prácticas de tu centro.","icon":"book-open","display_order":-40,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true,"curriculum_version":"default"},{"id":"e7301030-2026-4000-8000-000000000002","program_id":"kineo-es","academic_level_id":"83040b48-7a19-46d7-a61c-5a3d2d947fb6","code":"ES1-S2-PHYS","name":"Semestre 2 · Fisiología II","unit_type":"subject","description":"Socle complementario de revisión: 40 preguntas originales corregidas. Consulta también el curso y las prácticas de tu centro.","icon":"book-open","display_order":-39,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true,"curriculum_version":"default"},{"id":"e7301030-2026-4000-8000-000000000003","program_id":"kineo-es","academic_level_id":"83040b48-7a19-46d7-a61c-5a3d2d947fb6","code":"ES1-S2-PHYSICS","name":"Semestre 2 · Biofísica y Biomecánica","unit_type":"subject","description":"Socle complementario de revisión: 50 preguntas originales corregidas. Consulta también el curso y las prácticas de tu centro.","icon":"book-open","display_order":-38,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true,"curriculum_version":"default"},{"i