INSERT INTO public.curriculum_topics (id,unit_id,name,slug,description,display_order,content_language,translation_language,translation_mode,is_active) SELECT id,unit_id,name,slug,description,display_order,content_language,translation_language,translation_mode,is_active FROM jsonb_populate_recordset(null::public.curriculum_topics,'[{"id":"e7301030-2026-4000-8001-000000000001","unit_id":"e7301030-2026-4000-8000-000000000001","name":"Articulaciones, movimiento y referencias palpatorias","slug":"s2-joints","description":"Clasificar articulaciones por estructura y movilidad y utilizar referencias anatómicas como orientación, sin convertir una palpación aislada en diagnóstico.","display_order":1,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000002","unit_id":"e7301030-2026-4000-8000-000000000001","name":"Cintura escapular y miembro superior","slug":"s2-upper","description":"Relacionar músculos, trayecto articular y movimiento en hombro y codo. Diferenciar estabilización escapular y acción sobre el húmero.","display_order":2,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000003","unit_id":"e7301030-2026-4000-8000-000000000001","name":"Pelvis y miembro inferior","slug":"s2-lower","description":"Vincular grupos musculares con movimientos de cadera, rodilla y tobillo y reconocer que las tareas funcionales combinan varios segmentos.","display_order":3,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000004","unit_id":"e7301030-2026-4000-8000-000000000001","name":"Raquis: regiones, vértebras y discos","slug":"s2-spine","description":"Ubicar regiones vertebrales y distinguir cuerpo, arco, canal y forámenes; comprender que una referencia superficial no determina una lesión.","display_order":4,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000005","unit_id":"e7301030-2026-4000-8000-000000000001","name":"Sistema nervioso: organización y protección","slug":"s2-neuroanatomy","description":"Distinguir sistema central y periférico, sustancia gris y blanca, meninges y líquido cefalorraquídeo, y relacionarlos con circulación y vías.","display_order":5,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000006","unit_id":"e7301030-2026-4000-8000-000000000002","name":"Señal nerviosa: potenciales y sinapsis","slug":"s2-signal","description":"Distinguir potencial graduado y potencial de acción y seguir la transmisión de una señal sin confundir movimiento iónico y desplazamiento del impulso.","display_order":1,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000007","unit_id":"e7301030-2026-4000-8000-000000000002","name":"Somatosensación: receptores, vías y percepción","slug":"s2-somato","description":"Distinguir detección y percepción y relacionar modalidades sensitivas con vías generales, sin localizar una lesión a partir de una sola prueba.","display_order":2,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000008","unit_id":"e7301030-2026-4000-8000-000000000002","name":"Visión, audición y sistema vestibular","slug":"s2-senses","description":"Relacionar receptores de los sentidos especiales con orientación y equilibrio, evitando atribuir todo problema de estabilidad a un solo sistema.","display_order":3,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000009","unit_id":"e7301030-2026-4000-8000-000000000002","name":"Control motor, aprendizaje y funciones cognitivas","slug":"s2-motorlearn","description":"Relacionar unidad motora, ejecución, atención y memoria con práctica de tareas; comprender plasticidad sin prometer recuperación automática.","display_order":4,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000010","unit_id":"e7301030-2026-4000-8000-000000000003","name":"Temperatura, calor y transferencia térmica","slug":"s2-heat","description":"Distinguir temperatura y energía transferida y resolver cálculos sencillos de calentamiento sin convertirlos en parámetros de tratamiento.","display_order":1,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000011","unit_id":"e7301030-2026-4000-8000-000000000003","name":"Electricidad: tensión, corriente y resistencia","slug":"s2-electric","description":"Usar la ley de Ohm en un componente ideal y distinguir sus magnitudes, unidades y límites.","display_order":2,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000012","unit_id":"e7301030-2026-4000-8000-000000000003","name":"Ondas: frecuencia, periodo y longitud de onda","slug":"s2-waves","description":"Comparar magnitudes de una onda y resolver relaciones sencillas, distinguiendo fenómenos mecánicos y electromagnéticos.","display_order":3,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000013","unit_id":"e7301030-2026-4000-8000-000000000003","name":"Fuerzas, momentos y equilibrio","slug":"s2-torque","description":"Calcular momentos con brazo perpendicular y distinguir equilibrio de fuerzas y de momentos en modelos corporales simples.","display_order":4,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000014","unit_id":"e7301030-2026-4000-8000-000000000003","name":"Mecánica de tejidos: esfuerzo y deformación","slug":"s2-tissues","description":"Distinguir fuerza total, esfuerzo por área y deformación relativa; comprender el límite de los modelos elásticos aplicados a tejidos.","display_order":5,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000015","unit_id":"e7301030-2026-4000-8000-000000000004","name":"Planificar ejercicio: objetivos y variables FITT","slug":"s2-planning","description":"Construir un plan que relacione objetivos funcionales, frecuencia, intensidad, tiempo y tipo; separar ejemplos de aula y prescripciones individuales.","display_order":1,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000016","unit_id":"e7301030-2026-4000-8000-000000000004","name":"Seguridad, progresión y respuesta al ejercicio","slug":"s2-safety","description":"Reconocer condiciones de práctica, tolerancia y señales que exigen detener y reevaluar. Evitar la idea de que más esfuerzo siempre produce mejores resultados.","display_order":2,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000017","unit_id":"e7301030-2026-4000-8000-000000000004","name":"Fuerza, resistencia y equilibrio en tareas","slug":"s2-capacity","description":"Relacionar capacidades físicas con objetivos funcionales y distinguir cantidad de repeticiones, calidad y tolerancia.","display_order":3,"content_language":"es","translation_language":null,"translation_mode":"none","is_active":true},{"id":"e7301030-2026-4000-8001-000000000018","unit_id":"e7301030-2026-4000-8000-000000000005","name":"English · Asking about symptoms and history","slug":"s2-questionsen","description":"Practicar preguntas originales en inglés para localizar síntomas, conocer su inicio y pedir información con cortesía. Las correcciones se explican en castellano.","display_order":1,"content_language":"en","translation_language":"es","translation_mode":"bilingual","is_active":true},{"id":"e7301030-2026-4000-8001-000000000019","unit_id":"e7301030-2026-4000-8000-000000000005","name":"English · Body regions and movement vocabulary","slug":"s2-bodyen","description":"Relacionar vocabulario inglés de regiones y movimientos con la anatomía ya estudiada. Diferenciar términos próximos antes de leer instrucciones.","display_order":2,"content_language":"en","translation_language":"es","translation_mode":"bilingual","is_active":true},{"id":"e7301030-2026-4000-8001-000000000020","unit_id":"e7301030-2026-4000-8000-000000000005","name":"English · Reading instructions, modals and clinical notes","slug":"s2-readingen","description":"Interpretar frases breves en inglés y distinguir capacidad, petición, posibilidad y secuencia. No confundir una lectura lingüística con una indicación para un paciente real.","display_order":3,"content_language":"en","translation_language":"es","translation_mode":"bilingual","is_active":true}]'::jsonb);
INSERT INTO public.curriculum_lessons (id,topic_id,title,summary,content,key_points,source_files,display_order,validation_status,is_published) SELECT id,topic_id,title,summary,content,key_points,source_files,display_order,validation_status,is_published FROM jsonb_populate_recordset(null::public.curriculum_lessons,'[{"id":"e7301030-2026-4000-8002-000000000001","topic_id":"e7301030-2026-4000-8001-000000000001","title":"Articulaciones, movimiento y referencias palpatorias","summary":"Clasificar articulaciones por estructura y movilidad y utilizar referencias anatómicas como orientación, sin convertir una palpación aislada en diagnóstico.","content":"### Objetivos\n\nClasificar articulaciones por estructura y movilidad y utilizar referencias anatómicas como orientación, sin convertir una palpación aislada en diagnóstico.\n\n### Dos clasificaciones\n\nLa clasificación estructural diferencia articulaciones fibrosas, cartilaginosas y sinoviales. La funcional distingue sinartrosis, anfiartrosis y diartrosis. No son listas intercambiables: una clasificación explica la unión y otra el movimiento.\n\n### Articulación sinovial\n\nPresenta cavidad, cápsula, cartílago articular y líquido sinovial. Ligamentos y músculos contribuyen a la estabilidad mediante mecanismos diferentes. El cartílago facilita deslizamiento y distribución de cargas; no debe confundirse con un ligamento.\n\n### Exploración básica\n\nLa palpación localiza estructuras y recoge información que debe integrarse con historia y movimiento. Antes de tocar se explica la maniobra y se solicita aceptación. Se comparan lados cuando procede y se respetan dolor, intimidad y límites de competencia. Conocer el nombre de un relieve no prueba una lesión.\n\n### Ideas que debes poder justificar\n\n- La clasificación estructural considera la unión anatómica; la funcional considera movilidad.\n- Fibrosa, cartilaginosa y sinovial son categorías estructurales.\n- Diartrosis es una categoría funcional de movilidad; las sinoviales pertenecen a ella.\n- La cavidad articular es un rasgo estructural característico de las sinoviales.\n- El cartílago articular reduce fricción y participa en la transmisión de cargas.\n- Anfiartrosis designa una articulación con movimiento limitado.\n- Los ligamentos unen huesos y participan en la estabilidad de la articulación.\n- La exploración exige información comprensible, respeto y aceptación de la persona.\n- Las suturas son uniones fibrosas; hombro, rodilla y cadera son sinoviales.\n- Un hallazgo palpatorio aislado no basta para identificar toda la causa del problema.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Dos clasificaciones","Articulación sinovial","Exploración básica"],"source_files":[{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/9-1-classification-of-joints","type":"web","checked_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/9-4-synovial-joints","type":"web","checked_at":"2026-10-30"},{"url":"https://www.nhs.uk/conditions/physiotherapy/","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000002","topic_id":"e7301030-2026-4000-8001-000000000002","title":"Cintura escapular y miembro superior","summary":"Relacionar músculos, trayecto articular y movimiento en hombro y codo. Diferenciar estabilización escapular y acción sobre el húmero.","content":"### Objetivos\n\nRelacionar músculos, trayecto articular y movimiento en hombro y codo. Diferenciar estabilización escapular y acción sobre el húmero.\n\n### Base escapular\n\nLa escápula y la clavícula forman la cintura escapular. Trapecio, romboides y serrato anterior participan en su posición y control. El serrato anterior contribuye a la protracción; los romboides a la retracción.\n\n### Hombro\n\nEl manguito rotador incluye supraespinoso, infraespinoso, redondo menor y subescapular. Además de rotaciones y otras acciones, contribuye a la estabilidad glenohumeral. El deltoides es importante en abducción; no es parte del manguito.\n\n### Codo y análisis funcional\n\nBíceps braquial participa en flexión del codo y supinación. Tríceps es un extensor principal. Una misma tarea combina movimiento del húmero, escápula y antebrazo. No se debe atribuir una dificultad a un músculo solo porque participa en la tarea; la valoración distingue fuerza, movilidad, dolor y control.\n\n### Ideas que debes poder justificar\n\n- La cintura escapular está formada por escápula y clavícula.\n- El serrato anterior ayuda a desplazar la escápula hacia delante alrededor del tórax.\n- Los romboides contribuyen a retraer y estabilizar la escápula.\n- El infraespinoso integra el manguito junto con supraespinoso, redondo menor y subescapular.\n- El subescapular participa en rotación interna y estabilización glenohumeral.\n- El manguito ayuda a controlar la posición de la cabeza humeral durante el movimiento.\n- El bíceps braquial actúa sobre el codo y la orientación del antebrazo.\n- El tríceps braquial participa de forma principal en la extensión del codo.\n- La elevación del miembro superior requiere coordinación de varias estructuras.\n- El deltoides mueve el húmero pero no es uno de los cuatro músculos del manguito.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Base escapular","Hombro","Codo y análisis funcional"],"source_files":[{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/11-5-muscles-of-the-pectoral-girdle-and-upper-limbs","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000003","topic_id":"e7301030-2026-4000-8001-000000000003","title":"Pelvis y miembro inferior","summary":"Vincular grupos musculares con movimientos de cadera, rodilla y tobillo y reconocer que las tareas funcionales combinan varios segmentos.","content":"### Objetivos\n\nVincular grupos musculares con movimientos de cadera, rodilla y tobillo y reconocer que las tareas funcionales combinan varios segmentos.\n\n### Cadera\n\nIliopsoas comprende psoas mayor e ilíaco y participa en flexión. Glúteo mayor contribuye a extensión; glúteo medio y menor participan en abducción y control pélvico. Los aductores actúan en la región medial del muslo.\n\n### Rodilla\n\nEl cuádriceps incluye recto femoral y tres vastos y participa en extensión de rodilla. El recto femoral cruza también la cadera. Los isquiotibiales participan en flexión de rodilla y, con diferencias entre componentes, extensión de cadera.\n\n### Tobillo y tarea\n\nTibial anterior participa en dorsiflexión. Gastrocnemio y sóleo contribuyen a flexión plantar. Gastrocnemio cruza la rodilla; sóleo no. Levantarse, caminar y subir escalones exigen coordinación, fuerza y equilibrio. Una función muscular memorizada orienta la exploración, pero no constituye por sí sola un diagnóstico.\n\n### Ideas que debes poder justificar\n\n- El iliopsoas integra psoas mayor e ilíaco y participa en flexión de cadera.\n- El glúteo mayor es importante en la extensión de la cadera.\n- Los aductores del muslo participan en aproximar el fémur hacia la línea media.\n- El cuádriceps es un grupo extensor de la rodilla.\n- El recto femoral es biarticular y actúa sobre cadera y rodilla.\n- Los isquiotibiales participan en flexión de la rodilla.\n- El tibial anterior ayuda a elevar la parte anterior del pie.\n- La elevación sobre puntas requiere flexión plantar del tobillo.\n- El número de articulaciones cruzadas influye en la función de cada músculo.\n- La tarea de levantarse combina acciones y demandas en varios segmentos.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Cadera","Rodilla","Tobillo y tarea"],"source_files":[{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/11-6-appendicular-muscles-of-the-pelvic-girdle-and-lower-limbs","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000004","topic_id":"e7301030-2026-4000-8001-000000000004","title":"Raquis: regiones, vértebras y discos","summary":"Ubicar regiones vertebrales y distinguir cuerpo, arco, canal y forámenes; comprender que una referencia superficial no determina una lesión.","content":"### Objetivos\n\nUbicar regiones vertebrales y distinguir cuerpo, arco, canal y forámenes; comprender que una referencia superficial no determina una lesión.\n\n### Regiones\n\nEl modelo típico adulto comprende siete vértebras cervicales, doce torácicas y cinco lumbares, además de sacro y cóccix. Atlas es C1 y axis C2. Existen variantes, por lo que los números orientan el estudio anatómico general.\n\n### Elementos\n\nEl cuerpo vertebral soporta carga. El arco contribuye a delimitar el foramen vertebral; la sucesión forma el canal. Las apófisis son referencias y puntos de inserción. Los forámenes intervertebrales permiten paso de nervios espinales.\n\n### Discos y curvaturas\n\nUn disco intervertebral presenta anillo fibroso y núcleo pulposo. Se sitúa entre cuerpos vertebrales adyacentes, con excepciones como C1-C2. Las curvaturas cervical y lumbar se desarrollan después del nacimiento. Observar postura o palpar una apófisis debe interpretarse con historia y función; no basta para explicar dolor por sí solo.\n\n### Ideas que debes poder justificar\n\n- La región cervical típica comprende C1 a C7.\n- La región torácica comprende T1 a T12.\n- La región lumbar típica comprende L1 a L5.\n- Atlas es el nombre de la primera vértebra cervical.\n- Axis es la segunda vértebra cervical y presenta la apófisis odontoides.\n- El disco combina un anillo externo fibroso y un núcleo interno pulposo.\n- La sucesión de forámenes vertebrales delimita el canal que protege la médula.\n- Los forámenes intervertebrales proporcionan vías de paso a nervios espinales.\n- Las curvaturas cervical y lumbar se desarrollan después del nacimiento.\n- Una observación estructural aislada no determina su significado clínico.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Regiones","Elementos","Discos y curvaturas"],"source_files":[{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/7-3-the-vertebral-column","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000005","topic_id":"e7301030-2026-4000-8001-000000000005","title":"Sistema nervioso: organización y protección","summary":"Distinguir sistema central y periférico, sustancia gris y blanca, meninges y líquido cefalorraquídeo, y relacionarlos con circulación y vías.","content":"### Objetivos\n\nDistinguir sistema central y periférico, sustancia gris y blanca, meninges y líquido cefalorraquídeo, y relacionarlos con circulación y vías.\n\n### Organización\n\nEncéfalo y médula espinal forman el sistema central. Los nervios y ganglios periféricos conectan con el resto del cuerpo. El encéfalo incluye cerebro, diencéfalo, tronco y cerebelo. La coordinación no depende de una única región aislada.\n\n### Tejidos y protección\n\nLa sustancia gris contiene abundantes cuerpos celulares y sinapsis; la blanca contiene muchos axones mielinizados. Duramadre, aracnoides y piamadre son meninges. El líquido cefalorraquídeo circula en ventrículos y espacio subaracnoideo y contribuye a protección y homeostasis.\n\n### Vías y perfusión\n\nLas vías ascendentes transportan información sensitiva y las descendentes participan en control motor. Las raíces dorsales se relacionan con entrada sensitiva y las ventrales con salida motora. La irrigación encefálica recibe aportes carotídeos internos y vertebrobasilares. Estos esquemas orientan, pero no bastan para localizar clínicamente una lesión sin exploración.\n\n### Ideas que debes poder justificar\n\n- El sistema central está formado por encéfalo y médula espinal.\n- Los nervios espinales conectan el sistema central con estructuras periféricas.\n- La sustancia blanca contiene numerosos axones y su aspecto se relaciona con mielina.\n- Las meninges recubren y protegen estructuras del sistema central.\n- El LCR circula por el sistema ventricular y el espacio subaracnoideo.\n- Las vías ascendentes conducen información desde niveles inferiores hacia estructuras superiores.\n- Las raíces dorsales llevan información sensitiva al sistema central.\n- Las raíces ventrales contienen fibras de salida motora.\n- Las carótidas internas y arterias vertebrales aportan irrigación encefálica.\n- Un mapa anatómico ayuda a razonar, pero no equivale a un diagnóstico clínico.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Organización","Tejidos y protección","Vías y perfusión"],"source_files":[{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/13-2-the-central-nervous-system","type":"web","checked_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/13-3-circulation-and-the-central-nervous-system","type":"web","checked_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/14-2-central-processing","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000006","topic_id":"e7301030-2026-4000-8001-000000000006","title":"Señal nerviosa: potenciales y sinapsis","summary":"Distinguir potencial graduado y potencial de acción y seguir la transmisión de una señal sin confundir movimiento iónico y desplazamiento del impulso.","content":"### Objetivos\n\nDistinguir potencial graduado y potencial de acción y seguir la transmisión de una señal sin confundir movimiento iónico y desplazamiento del impulso.\n\n### Membrana excitable\n\nLos gradientes iónicos y la permeabilidad contribuyen al potencial de membrana. En el modelo neuronal, el interior en reposo es negativo respecto al exterior. La bomba sodio-potasio mantiene gradientes; no es la apertura rápida de los canales que produce cada fase del potencial.\n\n### Potenciales\n\nLos potenciales graduados varían con el estímulo y pueden sumarse. El potencial de acción se desencadena al alcanzar umbral y sigue un patrón de todo o nada. Un estímulo más intenso no aumenta indefinidamente su amplitud; la frecuencia de descarga puede aportar información.\n\n### Sinapsis\n\nEn una sinapsis química, la llegada del potencial al terminal favorece entrada de calcio y liberación de neurotransmisor. La respuesta postsináptica depende de receptores y canales. Una misma sustancia no es necesariamente excitadora en cualquier receptor. Excitación e inhibición contribuyen a la integración de señales.\n\n### Ideas que debes poder justificar\n\n- El voltaje de membrana expresa una diferencia entre interior y exterior.\n- La bomba contribuye a mantener gradientes que permiten la excitabilidad.\n- Los potenciales graduados varían y pueden contribuir a la suma de señales.\n- La amplitud del potencial de acción no aumenta proporcionalmente con cada aumento del estímulo.\n- Las señales graduadas pueden sumarse espacial o temporalmente e influir en alcanzar umbral.\n- La entrada de calcio presináptico participa en la liberación vesicular.\n- El neurotransmisor difunde y actúa sobre receptores postsinápticos.\n- El código de frecuencia puede variar sin un aumento proporcional de amplitud.\n- La inhibición reduce la probabilidad de disparo dentro de la integración postsináptica.\n- El receptor y los mecanismos postsinápticos condicionan el efecto de la señal.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Membrana excitable","Potenciales","Sinapsis"],"source_files":[{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/12-4-the-action-potential","type":"web","checked_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/12-5-communication-between-neurons","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000007","topic_id":"e7301030-2026-4000-8001-000000000007","title":"Somatosensación: receptores, vías y percepción","summary":"Distinguir detección y percepción y relacionar modalidades sensitivas con vías generales, sin localizar una lesión a partir de una sola prueba.","content":"### Objetivos\n\nDistinguir detección y percepción y relacionar modalidades sensitivas con vías generales, sin localizar una lesión a partir de una sola prueba.\n\n### Detección e interpretación\n\nLa sensación comienza con la detección de estímulos; la percepción supone procesamiento e interpretación. Mecanorreceptores detectan estímulos mecánicos, termorreceptores temperatura y nociceptores estímulos potencialmente lesivos. No toda señal sensitiva alcanza conciencia.\n\n### Modalidades y trayectos\n\nLa propiocepción aporta información sobre posición y movimiento. El sistema de columnas dorsales participa en tacto discriminativo, vibración y propiocepción consciente. La vía espinotalámica participa en dolor y temperatura. Las vías presentan cruces y relevos que deben estudiarse en mapas.\n\n### Valoración\n\nSe describe modalidad, región, condiciones de prueba y respuesta. Un hallazgo aislado no determina por sí solo una causa central o periférica. El dolor es una experiencia que debe recogerse en contexto; no se infiere su intensidad únicamente de una etiqueta anatómica. Se comparan datos de entrevista y exploración y se solicita supervisión si hay incertidumbre.\n\n### Ideas que debes poder justificar\n\n- La detección y la interpretación son procesos relacionados pero distinguibles.\n- Los mecanorreceptores responden a estímulos mecánicos.\n- La temperatura es una modalidad sensitiva diferenciada.\n- La nocicepción se relaciona con estímulos que amenazan la integridad tisular.\n- La propiocepción informa sobre el estado mecánico del cuerpo.\n- Las columnas dorsales participan en modalidades como vibración, tacto fino y propiocepción consciente.\n- El sistema espinotalámico participa en transmisión de estas modalidades.\n- Describir cómo se obtuvo el hallazgo permite interpretarlo y compararlo.\n- Las diferencias sensitivas requieren interpretación conjunta y control de la exploración.\n- Las señales se procesan y adquieren significado dentro del sistema nervioso.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Detección e interpretación","Modalidades y trayectos","Valoración"],"source_files":[{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/14-1-sensory-perception","type":"web","checked_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/14-2-central-processing","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000008","topic_id":"e7301030-2026-4000-8001-000000000008","title":"Visión, audición y sistema vestibular","summary":"Relacionar receptores de los sentidos especiales con orientación y equilibrio, evitando atribuir todo problema de estabilidad a un solo sistema.","content":"### Objetivos\n\nRelacionar receptores de los sentidos especiales con orientación y equilibrio, evitando atribuir todo problema de estabilidad a un solo sistema.\n\n### Visión\n\nLa retina contiene fotorreceptores. Los bastones son importantes con poca luz y los conos para color y detalle. La información visual contribuye a reconocer objetos y organizar acciones; no es una copia sin procesamiento.\n\n### Audición y equilibrio\n\nEn la cóclea, células ciliadas transforman estímulos mecánicos relacionados con sonido. El sistema vestibular del oído interno aporta información sobre movimientos y orientación de la cabeza. Los conductos semicirculares se relacionan con aceleración angular; utrículo y sáculo con aceleración lineal y orientación respecto a gravedad.\n\n### Integración\n\nEl equilibrio combina información vestibular, visual y somatosensorial con respuestas motoras. Cambiar iluminación o superficie modifica las demandas. Una dificultad de estabilidad no demuestra por sí sola una enfermedad del oído interno. Se describen condiciones y se realizan pruebas con protección adecuada y supervisión.\n\n### Ideas que debes poder justificar\n\n- Los fotorreceptores retinianos transforman estímulos luminosos.\n- Los bastones son sensibles en condiciones de baja iluminación.\n- Los conos participan en color y visión detallada.\n- La cóclea contiene receptores implicados en transducción del sonido.\n- Las células ciliadas convierten desplazamientos mecánicos en señales.\n- Su organización permite detectar cambios de movimiento angular.\n- Los órganos otolíticos contribuyen a detectar aceleración lineal y posición gravitatoria.\n- La estabilidad depende de integración sensorial y respuestas motoras.\n- La dependencia de información visual debe interpretarse con el resto de la valoración.\n- Distintos factores pueden limitar una tarea de estabilidad.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Visión","Audición y equilibrio","Integración"],"source_files":[{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/14-1-sensory-perception","type":"web","checked_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/14-2-central-processing","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000009","topic_id":"e7301030-2026-4000-8001-000000000009","title":"Control motor, aprendizaje y funciones cognitivas","summary":"Relacionar unidad motora, ejecución, atención y memoria con práctica de tareas; comprender plasticidad sin prometer recuperación automática.","content":"### Objetivos\n\nRelacionar unidad motora, ejecución, atención y memoria con práctica de tareas; comprender plasticidad sin prometer recuperación automática.\n\n### De la señal al músculo\n\nLa unidad motora comprende una neurona motora y las fibras que inerva. En la unión neuromuscular la acetilcolina desencadena cambios eléctricos; el calcio participa en activar la interacción actina-miosina. ATP es necesario para el ciclo contráctil y la relajación.\n\n### Ejecución y aprendizaje\n\nHacer mejor una tarea durante una sesión no equivale siempre a aprendizaje duradero. Se comprueba retención y aplicación a otras situaciones. La práctica se organiza según objetivos, dificultad y posibilidades de la persona. La plasticidad describe capacidad de cambio del sistema nervioso, no una garantía de resultado.\n\n### Cognición\n\nAtención permite seleccionar información; memoria implica codificar, almacenar y recuperar. La memoria de trabajo mantiene y manipula información para una tarea. Las funciones ejecutivas ayudan a planificar, inhibir distracciones y ajustar acciones. La motivación influye en la participación, pero no reemplaza seguridad ni capacidad física.\n\n### Ideas que debes poder justificar\n\n- La unidad motora conecta una neurona motora con sus fibras musculares.\n- La acetilcolina participa en activar la membrana de la fibra muscular.\n- El calcio modifica el complejo regulador y permite la interacción de filamentos.\n- ATP participa en los ciclos de interacción actina-miosina y en procesos de relajación.\n- La memoria reúne procesos para incorporar, conservar y recuperar información.\n- La memoria de trabajo sostiene información útil para la actividad en curso.\n- Las funciones ejecutivas ayudan a organizar conducta dirigida a objetivos.\n- La mejoría inmediata no demuestra por sí sola aprendizaje duradero.\n- La capacidad de cambio no equivale a promesa de recuperación automática.\n- La carga de información y las distracciones pueden afectar a la ejecución y comprensión.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["De la señal al músculo","Ejecución y aprendizaje","Cognición"],"source_files":[{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/10-3-muscle-fiber-contraction-and-relaxation","type":"web","checked_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/14-3-motor-responses","type":"web","checked_at":"2026-10-30"},{"url":"https://openstax.org/books/psychology-2e/pages/8-1-how-memory-functions","type":"web","checked_at":"2026-10-30"},{"url":"https://openstax.org/books/psychology-2e/pages/8-4-ways-to-enhance-memory","type":"web","checked_at":"2026-10-30"},{"url":"https://www.ninds.nih.gov/health-information/public-education/brain-basics/brain-basics-life-and-death-neuron","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000010","topic_id":"e7301030-2026-4000-8001-000000000010","title":"Temperatura, calor y transferencia térmica","summary":"Distinguir temperatura y energía transferida y resolver cálculos sencillos de calentamiento sin convertirlos en parámetros de tratamiento.","content":"### Objetivos\n\nDistinguir temperatura y energía transferida y resolver cálculos sencillos de calentamiento sin convertirlos en parámetros de tratamiento.\n\n### Magnitudes\n\nTemperatura expresa un estado térmico; calor es energía transferida por diferencia de temperatura. El calor se expresa en julios, no en grados Celsius. En equilibrio térmico no hay flujo neto de calor entre los sistemas considerados.\n\n### Transferencias\n\nConducción ocurre mediante interacción en materia sin transporte macroscópico de esta; convección implica movimiento de un fluido; radiación utiliza ondas electromagnéticas. Distintos materiales pueden sentirse diferentes a igual temperatura por sus propiedades de transferencia.\n\n### Modelo de cálculo\n\nSin cambio de fase y suponiendo calor específico constante, Q = m·c·ΔT. Masa, capacidad térmica específica y variación de temperatura son factores distintos. Los ejemplos son modelos físicos de aula; no determinan dosis ni seguridad de una aplicación clínica.\n\n### Ideas que debes poder justificar\n\n- Temperatura y calor son magnitudes distintas y no se suman como si fueran equivalentes.\n- El calor es una transferencia energética y se expresa en julios.\n- En equilibrio térmico tienen la misma temperatura y no existe flujo neto de calor.\n- La convección transporta energía mediante movimiento de líquido o gas.\n- La radiación no requiere el contacto material propio de la conducción.\n- La relación conecta masa, calor específico y cambio de temperatura bajo sus supuestos.\n- El producto 2 por 1000 por 3 da 6000 julios.\n- La relación es proporcional a la variación de temperatura cuando se mantienen los demás factores.\n- La sensación térmica depende también del flujo de energía y las propiedades del material.\n- Un modelo simplificado no determina una dosis terapéutica segura.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Magnitudes","Transferencias","Modelo de cálculo"],"source_files":[{"url":"https://openstax.org/books/university-physics-volume-2/pages/1-1-temperature-and-thermal-equilibrium","type":"web","checked_at":"2026-10-30"},{"url":"https://openstax.org/books/university-physics-volume-2/pages/1-4-heat-transfer-specific-heat-and-calorimetry","type":"web","checked_at":"2026-10-30"},{"url":"https://openstax.org/books/university-physics-volume-2/pages/1-6-mechanisms-of-heat-transfer","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000011","topic_id":"e7301030-2026-4000-8001-000000000011","title":"Electricidad: tensión, corriente y resistencia","summary":"Usar la ley de Ohm en un componente ideal y distinguir sus magnitudes, unidades y límites.","content":"### Objetivos\n\nUsar la ley de Ohm en un componente ideal y distinguir sus magnitudes, unidades y límites.\n\n### Magnitudes y unidades\n\nTensión es diferencia de potencial y se mide en voltios. Corriente es flujo de carga por tiempo y se mide en amperios. Resistencia relaciona tensión y corriente en un componente óhmico y se expresa en ohmios. No son sinónimos.\n\n### Modelo óhmico\n\nPara un componente óhmico bajo condiciones constantes, V = I·R. Por tanto I = V/R y R = V/I. La proporcionalidad no describe todos los materiales o dispositivos en cualquier condición. Los tejidos biológicos presentan propiedades más complejas que una resistencia ideal.\n\n### Resolver y delimitar\n\nAntes de calcular, identifica la incógnita y convierte miliamperios a amperios. Después revisa unidades y orden de magnitud. Los ejemplos representan circuitos de aula y no configuraciones de electroterapia. Un cálculo eléctrico aislado no autoriza a aplicar corriente a una persona.\n\n### Ideas que debes poder justificar\n\n- La corriente expresa carga por unidad de tiempo y se mide en amperios.\n- El voltio es la unidad de tensión o diferencia de potencial.\n- La resistencia se expresa en ohmios.\n- En un componente óhmico, tensión, intensidad y resistencia se relacionan por V=IR.\n- I=V/R: 12 dividido entre 6 da 2 amperios.\n- R=V/I: 10 dividido entre 0,5 da 20 ohmios.\n- La corriente es inversamente proporcional a la resistencia con tensión constante.\n- Mil miliamperios equivalen a un amperio.\n- Ohm es un modelo de comportamiento y no una descripción universal de todos los componentes.\n- Los ejemplos de circuitos no equivalen a indicaciones clínicas.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Magnitudes y unidades","Modelo óhmico","Resolver y delimitar"],"source_files":[{"url":"https://openstax.org/books/university-physics-volume-2/pages/9-4-ohms-law","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000012","topic_id":"e7301030-2026-4000-8001-000000000012","title":"Ondas: frecuencia, periodo y longitud de onda","summary":"Comparar magnitudes de una onda y resolver relaciones sencillas, distinguiendo fenómenos mecánicos y electromagnéticos.","content":"### Objetivos\n\nComparar magnitudes de una onda y resolver relaciones sencillas, distinguiendo fenómenos mecánicos y electromagnéticos.\n\n### Variables\n\nAmplitud describe el máximo desplazamiento respecto al equilibrio en el modelo oscilatorio. Periodo es tiempo por ciclo y frecuencia ciclos por segundo. Longitud de onda es distancia espacial entre puntos equivalentes consecutivos.\n\n### Relaciones\n\nPara una onda periódica, f=1/T y v=f·λ. Frecuencia, rapidez y longitud son magnitudes distintas. En un mismo medio y con rapidez constante, aumentar frecuencia reduce longitud de onda. Cambiar el medio puede cambiar rapidez y longitud.\n\n### Tipos y aplicación\n\nLas ondas mecánicas requieren un medio material; las electromagnéticas pueden propagarse en vacío. En una onda transversal la oscilación es perpendicular a la propagación; en una longitudinal es paralela. El sonido en aire es un ejemplo longitudinal. Ultrasonido es sonido de frecuencia superior al límite audible típico, no una corriente eléctrica. Estos conceptos no proporcionan una dosificación terapéutica.\n\n### Ideas que debes poder justificar\n\n- La frecuencia mide número de ciclos por unidad de tiempo.\n- Un herzio equivale a un ciclo por segundo.\n- f=1/T: uno dividido entre 0,02 son 50 hercios.\n- λ=v/f: 10 dividido entre 5 da 2 metros.\n- La relación v=fλ exige que frecuencia y longitud varíen inversamente si v es constante.\n- El periodo es una duración, mientras que la longitud de onda es una distancia.\n- La amplitud expresa la magnitud máxima de la oscilación.\n- Las ondas mecánicas necesitan un medio; las electromagnéticas pueden viajar en vacío.\n- La orientación de la oscilación distingue ondas longitudinales y transversales.\n- La naturaleza física de una onda sonora no es la de una corriente eléctrica.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Variables","Relaciones","Tipos y aplicación"],"source_files":[{"url":"https://openstax.org/books/university-physics-volume-1/pages/16-1-traveling-waves","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000013","topic_id":"e7301030-2026-4000-8001-000000000013","title":"Fuerzas, momentos y equilibrio","summary":"Calcular momentos con brazo perpendicular y distinguir equilibrio de fuerzas y de momentos en modelos corporales simples.","content":"### Objetivos\n\nCalcular momentos con brazo perpendicular y distinguir equilibrio de fuerzas y de momentos en modelos corporales simples.\n\n### Fuerzas y momentos\n\nUna fuerza tiene magnitud, dirección y punto de aplicación. Su efecto rotatorio respecto a un eje depende del brazo perpendicular: M=F·d. La distancia utilizada no es cualquier longitud del segmento, sino la perpendicular desde el eje a la línea de acción.\n\n### Equilibrio\n\nUn cuerpo rígido en equilibrio estático cumple suma de fuerzas igual a cero y suma de momentos igual a cero. Anular solo una de esas sumas no garantiza ambas. Fuerzas iguales pueden producir momentos distintos si sus brazos difieren.\n\n### Modelo corporal\n\nHuesos se representan a veces como segmentos rígidos y articulaciones como ejes, pero los tejidos reales deforman y el control es dinámico. Un brazo muscular corto puede exigir una fuerza alta para equilibrar una carga externa. Los cálculos de aula no dan directamente fuerzas internas reales sin conocer geometría y supuestos.\n\n### Ideas que debes poder justificar\n\n- El momento respecto al eje es fuerza por distancia perpendicular a su línea de acción.\n- 20 por 0,3 da 6 newton-metro.\n- La geometría de la línea de acción determina el brazo efectivo.\n- Sin brazo perpendicular no existe momento de esa fuerza respecto al eje.\n- El equilibrio estático exige equilibrio traslacional y rotacional.\n- El momento depende tanto de fuerza como de brazo perpendicular.\n- F=M/d: 10 dividido entre 0,05 da 200 newtons.\n- También debe anularse la resultante de fuerzas.\n- Aumentar el brazo perpendicular aumenta el momento con la misma fuerza.\n- Los modelos simplifican y deben interpretarse dentro de sus condiciones.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Fuerzas y momentos","Equilibrio","Modelo corporal"],"source_files":[{"url":"https://openstax.org/books/university-physics-volume-1/pages/10-6-torque","type":"web","checked_at":"2026-10-30"},{"url":"https://openstax.org/books/university-physics-volume-1/pages/12-1-conditions-for-static-equilibrium","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000014","topic_id":"e7301030-2026-4000-8001-000000000014","title":"Mecánica de tejidos: esfuerzo y deformación","summary":"Distinguir fuerza total, esfuerzo por área y deformación relativa; comprender el límite de los modelos elásticos aplicados a tejidos.","content":"### Objetivos\n\nDistinguir fuerza total, esfuerzo por área y deformación relativa; comprender el límite de los modelos elásticos aplicados a tejidos.\n\n### Esfuerzo\n\nEl esfuerzo mecánico se expresa como fuerza por área. Una misma fuerza distribuida en áreas diferentes no produce el mismo esfuerzo medio. Tracción alarga, compresión acorta y cizalla implica acciones tangenciales.\n\n### Deformación\n\nLa deformación longitudinal relativa se calcula como ΔL/L inicial y no tiene unidades. En el tramo lineal elástico, esfuerzo = módulo elástico por deformación. Un módulo mayor significa mayor rigidez en ese modelo, no necesariamente mayor tolerancia a lesión.\n\n### Límites\n\nLa elasticidad describe recuperación tras retirar carga dentro del rango apropiado. Fuera de ciertos límites pueden aparecer cambios permanentes. Los tejidos biológicos no se describen por una única recta en todas las condiciones; el tiempo y la velocidad de carga también importan. No se derivan umbrales de lesión individuales a partir de un ejercicio matemático.\n\n### Ideas que debes poder justificar\n\n- El esfuerzo permite distinguir una fuerza total de cómo se distribuye sobre un área.\n- Un pascal equivale a un newton por metro cuadrado.\n- Con F constante, esfuerzo=F/A aumenta al reducir el área.\n- La deformación relativa relaciona el alargamiento con la longitud de referencia.\n- ΔL/L0 es 2/100=0,02, equivalente al 2 %.\n- Al dividir dos longitudes, sus unidades se cancelan.\n- En esfuerzo=E·deformación, un E mayor representa mayor rigidez lineal.\n- La tracción produce elongación; la compresión tiende a acortar.\n- La cizalla se relaciona con fuerzas tangenciales.\n- La simplificación lineal tiene límites y no proporciona un umbral individual de lesión.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Esfuerzo","Deformación","Límites"],"source_files":[{"url":"https://openstax.org/books/university-physics-volume-1/pages/12-3-stress-strain-and-elastic-modulus","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000015","topic_id":"e7301030-2026-4000-8001-000000000015","title":"Planificar ejercicio: objetivos y variables FITT","summary":"Construir un plan que relacione objetivos funcionales, frecuencia, intensidad, tiempo y tipo; separar ejemplos de aula y prescripciones individuales.","content":"### Objetivos\n\nConstruir un plan que relacione objetivos funcionales, frecuencia, intensidad, tiempo y tipo; separar ejemplos de aula y prescripciones individuales.\n\n### Empezar por la función\n\nSe recoge qué actividad importa a la persona y qué la limita. Un objetivo concreto permite valorar cambios; «mejorar todo» no orienta bien la selección de tareas. La planificación también considera entorno, experiencia, recursos y preferencias.\n\n### Variables FITT\n\nFrecuencia indica cuántas sesiones; intensidad cuánto esfuerzo; tiempo cuánto dura; tipo qué actividad se realiza. Modificar una variable no equivale a modificar todas. Un plan necesita progresión y seguimiento, no solo una lista de ejercicios.\n\n### Medir y adaptar\n\nEl esfuerzo puede estimarse por percepción y otras medidas según contexto. La intensidad relativa depende de la persona: una misma actividad no exige lo mismo a todo el mundo. Las recomendaciones poblacionales de actividad física no sustituyen una prescripción terapéutica. Los ejemplos de esta ficha son de razonamiento y no pautas individuales.\n\n### Ideas que debes poder justificar\n\n- Frecuencia describe la repetición de sesiones o exposiciones en el tiempo.\n- Intensidad expresa cuánto esfuerzo requiere la actividad.\n- Tiempo se refiere a duración y debe especificarse con unidades.\n- Tipo describe la actividad elegida, como caminar o trabajo de fuerza.\n- Un objetivo funcional claro ayuda a seleccionar y evaluar actividades.\n- Una misma actividad puede representar esfuerzos relativos distintos.\n- La capacidad individual modifica el esfuerzo relativo de la misma actividad.\n- La referencia inicial facilita evaluar cambios y ajustar el plan.\n- La rehabilitación necesita adaptar objetivos y cargas a la situación.\n- Modificar varias demandas simultáneamente dificulta interpretar tolerancia y ajustar.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Empezar por la función","Variables FITT","Medir y adaptar"],"source_files":[{"url":"https://acsm.org/education-resources/books/guidelines-exercise-testing-prescription/","type":"web","checked_at":"2026-10-30"},{"url":"https://www.who.int/news-room/fact-sheets/detail/physical-activity","type":"web","checked_at":"2026-10-30"},{"url":"https://www.cdc.gov/physical-activity-basics/measuring/index.html","type":"web","checked_at":"2026-10-30"},{"url":"https://medlineplus.gov/ency/patientinstructions/000859.htm","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000016","topic_id":"e7301030-2026-4000-8001-000000000016","title":"Seguridad, progresión y respuesta al ejercicio","summary":"Reconocer condiciones de práctica, tolerancia y señales que exigen detener y reevaluar. Evitar la idea de que más esfuerzo siempre produce mejores resultados.","content":"### Objetivos\n\nReconocer condiciones de práctica, tolerancia y señales que exigen detener y reevaluar. Evitar la idea de que más esfuerzo siempre produce mejores resultados.\n\n### Preparar\n\nSe revisan tarea, entorno, material y capacidades. Aprender la técnica y empezar de manera gradual contribuye a reducir riesgos. Un calentamiento progresivo no equivale a una garantía de ausencia de lesión.\n\n### Progresar\n\nFrecuencia, duración e intensidad son dimensiones que conviene controlar. Se adapta la actividad según respuesta y recuperación, evitando aumentos bruscos o cambios simultáneos sin seguimiento. La fatiga persistente puede indicar que se necesita revisar la carga.\n\n### Señales y límites\n\nDolor intenso, una lesión evidente o dolor torácico durante ejercicio requieren detener y buscar valoración apropiada; el dolor torácico exige atención urgente. El estudiante no interpreta una fórmula ni una recomendación general como autorización para continuar ante síntomas preocupantes. La seguridad forma parte del plan y del diálogo con la persona.\n\n### Ideas que debes poder justificar\n\n- La progresión excesivamente rápida figura entre los factores de riesgo evitables.\n- El ajuste, el estado y el uso del material influyen en la seguridad.\n- Controlar variables permite relacionar cambios de carga y tolerancia.\n- El calentamiento es una medida preparatoria, no una garantía absoluta.\n- El dolor torácico durante o después de ejercicio requiere valoración urgente.\n- Un síntoma preocupante obliga a revisar la actividad y la necesidad de atención.\n- El dolor no demuestra por sí solo eficacia y puede exigir detener o adaptar.\n- La fatiga persistente es un dato que debe integrarse en la revisión del plan.\n- La seguridad depende también del espacio, apoyos y supervisión.\n- La respuesta posterior también informa sobre tolerancia y dosificación.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Preparar","Progresar","Señales y límites"],"source_files":[{"url":"https://medlineplus.gov/ency/patientinstructions/000859.htm","type":"web","checked_at":"2026-10-30"},{"url":"https://www.nhs.uk/conditions/physiotherapy/","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000017","topic_id":"e7301030-2026-4000-8001-000000000017","title":"Fuerza, resistencia y equilibrio en tareas","summary":"Relacionar capacidades físicas con objetivos funcionales y distinguir cantidad de repeticiones, calidad y tolerancia.","content":"### Objetivos\n\nRelacionar capacidades físicas con objetivos funcionales y distinguir cantidad de repeticiones, calidad y tolerancia.\n\n### Capacidades diferentes\n\nFuerza es capacidad de producir tensión o fuerza; resistencia se relaciona con sostener esfuerzo. El trabajo aeróbico, el fortalecimiento y las tareas de equilibrio tienen demandas diferentes y pueden combinarse. Una categoría no sustituye automáticamente a otra.\n\n### Seleccionar tareas\n\nLevantarse de una silla exige fuerza, coordinación y estabilidad. Caminar puede utilizarse para trabajar tolerancia al esfuerzo según condiciones. Una tarea de equilibrio se adapta mediante apoyos, superficie y demandas sensoriales, sin asumir que sea adecuada para cualquier persona.\n\n### Observar ejecución\n\nContar repeticiones no describe toda la tarea. Se observa control, amplitud, síntomas y recuperación. La percepción de esfuerzo y el test del habla pueden ayudar a describir intensidad aeróbica en contextos apropiados. Son herramientas orientativas, no pruebas que descarten enfermedades ni sustitutos de evaluación.\n\n### Ideas que debes poder justificar\n\n- El fortalecimiento busca mejorar la capacidad de generar fuerza según objetivos.\n- La resistencia cardiorrespiratoria participa en sostener actividades como caminar.\n- Levantarse exige acciones coordinadas de varios segmentos.\n- El número de repeticiones no describe por sí solo la calidad o tolerancia.\n- La calidad y tolerancia pueden limitar la progresión aunque se complete la cantidad prevista.\n- El habla puede orientar intensidad aeróbica sin ser una prueba diagnóstica.\n- El test del habla es una regla orientativa para describir intensidad.\n- Las condiciones mecánicas y sensoriales modifican las demandas de estabilidad.\n- La estabilidad combina entradas sensoriales y control motor.\n- La selección se fundamenta en valoración, función y preferencias.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Capacidades diferentes","Seleccionar tareas","Observar ejecución"],"source_files":[{"url":"https://www.who.int/news-room/fact-sheets/detail/physical-activity","type":"web","checked_at":"2026-10-30"},{"url":"https://www.cdc.gov/physical-activity-basics/measuring/index.html","type":"web","checked_at":"2026-10-30"},{"url":"https://www.nhs.uk/conditions/physiotherapy/","type":"web","checked_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/14-1-sensory-perception","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000018","topic_id":"e7301030-2026-4000-8001-000000000018","title":"English · Asking about symptoms and history","summary":"Practicar preguntas originales en inglés para localizar síntomas, conocer su inicio y pedir información con cortesía. Las correcciones se explican en castellano.","content":"### Objetivos\n\nPracticar preguntas originales en inglés para localizar síntomas, conocer su inicio y pedir información con cortesía. Las correcciones se explican en castellano.\n\n### Question words\n\nWhere pregunta lugar; when momento; how long duración; how often frecuencia. En una entrevista se elige la pregunta según el dato que falta. No basta reconocer una palabra clínica si se interpreta mal la pregunta.\n\n### Question structure\n\nCon be se invierte sujeto y verbo: Are you comfortable? Con verbos de presente simple se usan do o does: Does it hurt? En pasado simple se usa did seguido de forma base: When did it start? Con modales: Can you move it? No se añade does delante de can.\n\n### Polite requests\n\nCould you ...? permite una petición cortés. Se puede pedir que la persona repita o muestre una tarea. Los ejemplos son práctica lingüística original y no un cuestionario clínico oficial. Comprender la respuesta importa tanto como construir una frase correcta.\n\n### Ideas que debes poder justificar\n\n- Where pregunta por el lugar; las otras preguntas buscan inicio, frecuencia o duración.\n- When did it start? pregunta cuándo empezó el problema.\n- Después de does se usa la forma base hurt.\n- Did forma la pregunta de pasado y el verbo principal queda en forma base.\n- How long busca duración; no debe confundirse con how often.\n- How often pregunta con qué frecuencia ocurre algo.\n- Could va seguido de sujeto y verbo base en esta petición.\n- Con be se invierte el orden sin añadir do.\n- La respuesta da un momento de inicio y corresponde a una pregunta con when.\n- Las preguntas con can no necesitan do y usan verbo base.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Question words","Question structure","Polite requests"],"source_files":[{"url":"https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/question-forms","type":"web","checked_at":"2026-10-30"},{"url":"https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/can-could","type":"web","checked_at":"2026-10-30"},{"url":"https://www.nhs.uk/conditions/physiotherapy/","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000019","topic_id":"e7301030-2026-4000-8001-000000000019","title":"English · Body regions and movement vocabulary","summary":"Relacionar vocabulario inglés de regiones y movimientos con la anatomía ya estudiada. Diferenciar términos próximos antes de leer instrucciones.","content":"### Objetivos\n\nRelacionar vocabulario inglés de regiones y movimientos con la anatomía ya estudiada. Diferenciar términos próximos antes de leer instrucciones.\n\n### Regions\n\nShoulder es hombro; elbow codo; wrist muñeca; hip cadera; knee rodilla y ankle tobillo. Upper limb y lower limb designan miembro superior e inferior. En uso anatómico, arm y forearm distinguen brazo y antebrazo; una descripción cotidiana puede ser menos precisa.\n\n### Movement\n\nBend y straighten suelen indicar doblar y enderezar en consignas sencillas. Flexion y extension son términos anatómicos. Rotate significa girar; lift, elevar. Se confirma qué segmento y dirección se piden en lugar de traducir sin contexto.\n\n### From words to function\n\nStrength se relaciona con fuerza, balance con equilibrio y range of motion con amplitud de movimiento. Weakness y stiffness no son sinónimos: una describe debilidad y la otra rigidez. Estos equivalentes ayudan a comprender, pero la traducción de un síntoma no equivale a su diagnóstico.\n\n### Ideas que debes poder justificar\n\n- Elbow corresponde al codo, situado entre brazo y antebrazo.\n- Wrist significa muñeca.\n- Knee es rodilla; no debe confundirse con otras articulaciones.\n- Ankle designa el tobillo.\n- Straighten indica enderezar; en esta consigna corresponde a extender la rodilla.\n- Bend the elbow significa doblar o flexionar el codo.\n- Range of motion se relaciona con amplitud o rango de movimiento.\n- Weakness es debilidad y stiffness es rigidez.\n- Stiffness describe rigidez; no equivale a debilidad.\n- La nota describe un hallazgo de movilidad del hombro y no prueba una lesión específica.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Regions","Movement","From words to function"],"source_files":[{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/11-5-muscles-of-the-pectoral-girdle-and-upper-limbs","type":"web","checked_at":"2026-10-30"},{"url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/11-6-appendicular-muscles-of-the-pelvic-girdle-and-lower-limbs","type":"web","checked_at":"2026-10-30"},{"url":"https://www.nhs.uk/conditions/physiotherapy/","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true},{"id":"e7301030-2026-4000-8002-000000000020","topic_id":"e7301030-2026-4000-8001-000000000020","title":"English · Reading instructions, modals and clinical notes","summary":"Interpretar frases breves en inglés y distinguir capacidad, petición, posibilidad y secuencia. No confundir una lectura lingüística con una indicación para un paciente real.","content":"### Objetivos\n\nInterpretar frases breves en inglés y distinguir capacidad, petición, posibilidad y secuencia. No confundir una lectura lingüística con una indicación para un paciente real.\n\n### Meaning and grammar\n\nCan puede expresar capacidad o permiso según contexto. Could puede introducir una petición cortés y might una posibilidad. Tras estos modales se emplea forma base del verbo. La elección depende del significado de la frase completa.\n\n### Sequence and information\n\nBefore y after ordenan acciones; between indica intervalo o posición según la frase. Una nota puede describir symptoms, medical history, strength o balance. Se distingue lo observado de una causa no demostrada. Un hallazgo escrito no debe convertirse automáticamente en diagnóstico.\n\n### Word families and reading\n\nPhysiotherapy nombra una disciplina o atención; physiotherapist a la persona profesional; rehabilitation a un proceso. En los ejercicios siguientes, las notas y consignas son originales y breves. Lee el dato explícito, evita añadir supuestos y comprueba pronombres, negaciones y unidades.\n\n### Ideas que debes poder justificar\n\n- En esta frase can expresa capacidad para hacer una tarea.\n- Could you ...? formula una petición cortés.\n- Might indica posibilidad y no certeza.\n- Can va seguido de la forma base stand.\n- Before sitúa la revisión de instrucciones antes del inicio.\n- After significa después y establece la secuencia.\n- Physiotherapist designa al profesional; physiotherapy designa la disciplina o atención.\n- Reports pain registra lo que comunica la persona y no identifica por sí solo la causa.\n- La frase menciona una evaluación de equilibrio en la primera consulta.\n- Discussed informa de una conversación; no demuestra cumplimiento ni resultado.\n\n### Comprobación\n\nResponde sin mirar la ficha. Justifica tu elección e identifica por qué las otras opciones no encajan. Si fallas un cálculo, revisa fórmula, unidades y orden de magnitud. Vuelve a las dudas en otra sesión.\n\nMaterial original de entrenamiento, complementario al curso UVic; no es un examen oficial.","key_points":["Meaning and grammar","Sequence and information","Word families and reading"],"source_files":[{"url":"https://learnenglish.britishcouncil.org/free-resources/grammar/a1-a2/question-forms","type":"web","checked_at":"2026-10-30"},{"url":"https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/can-could","type":"web","checked_at":"2026-10-30"},{"url":"https://learnenglish.britishcouncil.org/free-resources/grammar/english-grammar-reference/modal-verbs","type":"web","checked_at":"2026-10-30"},{"url":"https://www.nhs.uk/conditions/physiotherapy/","type":"web","checked_at":"2026-10-30"}],"display_order":1,"validation_status":"source_validated","is_published":true}]'::jsonb);
