text":"Epífisis, diáfisis y metáfisis","correct":false}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":2,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/9-1-classification-of-joints","https://openstax.org/books/anatomy-and-physiology-2e/pages/9-4-synovial-joints","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000003","topic_id":"e7301030-2026-4000-8001-000000000001","question_text":"¿Qué caracteriza una diartrosis?","explanation":"Diartrosis es una categoría funcional de movilidad; las sinoviales pertenecen a ella.","options":[{"text":"Ausencia obligatoria de movimiento","correct":false},{"text":"Fusión ósea por definición","correct":false},{"text":"Movilidad libre en la clasificación funcional","correct":true},{"text":"Solo una unión por cartílago","correct":false}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":3,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/9-1-classification-of-joints","https://openstax.org/books/anatomy-and-physiology-2e/pages/9-4-synovial-joints","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000004","topic_id":"e7301030-2026-4000-8001-000000000001","question_text":"¿Qué rasgo distingue una articulación sinovial?","explanation":"La cavidad articular es un rasgo estructural característico de las sinoviales.","options":[{"text":"Unión directa continua por fibrocartílago en toda la superficie","correct":false},{"text":"Ausencia de cápsula en todos los casos","correct":false},{"text":"Fusión de ambos huesos","correct":false},{"text":"Cavidad articular","correct":true}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":4,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/9-1-classification-of-joints","https://openstax.org/books/anatomy-and-physiology-2e/pages/9-4-synovial-joints","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000005","topic_id":"e7301030-2026-4000-8001-000000000001","question_text":"¿Qué tejido cubre habitualmente las superficies articulares sinoviales?","explanation":"El cartílago articular reduce fricción y participa en la transmisión de cargas.","options":[{"text":"Cartílago hialino articular","correct":true},{"text":"Epitelio intestinal","correct":false},{"text":"Tejido nervioso","correct":false},{"text":"Músculo liso","correct":false}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":5,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/9-1-classification-of-joints","https://openstax.org/books/anatomy-and-physiology-2e/pages/9-4-synovial-joints","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000006","topic_id":"e7301030-2026-4000-8001-000000000001","question_text":"¿Qué categoría funcional describe movilidad limitada?","explanation":"Anfiartrosis designa una articulación con movimiento limitado.","options":[{"text":"Diartrosis","correct":false},{"text":"Anfiartrosis","correct":true},{"text":"Solo articulación trocoide","correct":false},{"text":"Solo articulación esferoidea","correct":false}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":6,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/9-1-classification-of-joints","https://openstax.org/books/anatomy-and-physiology-2e/pages/9-4-synovial-joints","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000007","topic_id":"e7301030-2026-4000-8001-000000000001","question_text":"¿Qué estructura conecta huesos y contribuye a limitar movimientos excesivos?","explanation":"Los ligamentos unen huesos y participan en la estabilidad de la articulación.","options":[{"text":"Tendón como definición general","correct":false},{"text":"Alvéolo","correct":false},{"text":"Ligamento","correct":true},{"text":"Vaina de mielina","correct":false}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":7,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/9-1-classification-of-joints","https://openstax.org/books/anatomy-and-physiology-2e/pages/9-4-synovial-joints","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000008","topic_id":"e7301030-2026-4000-8001-000000000001","question_text":"Antes de palpar una zona, ¿qué conducta es adecuada?","explanation":"La exploración exige información comprensible, respeto y aceptación de la persona.","options":[{"text":"Tocar sin aviso para evitar preguntas","correct":false},{"text":"Insistir ante rechazo","correct":false},{"text":"Omitir la intimidad","correct":false},{"text":"Explicar el procedimiento y obtener aceptación","correct":true}],"difficulty":2,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":8,"validation_status":"source_validated","is_published":true,"question_type":"clinical_case","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/9-1-classification-of-joints","https://openstax.org/books/anatomy-and-physiology-2e/pages/9-4-synovial-joints","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000009","topic_id":"e7301030-2026-4000-8001-000000000001","question_text":"¿Qué ejemplo corresponde a una articulación fibrosa?","explanation":"Las suturas son uniones fibrosas; hombro, rodilla y cadera son sinoviales.","options":[{"text":"Sutura craneal","correct":true},{"text":"Articulación glenohumeral","correct":false},{"text":"Articulación de rodilla","correct":false},{"text":"Articulación de cadera","correct":false}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":9,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/9-1-classification-of-joints","https://openstax.org/books/anatomy-and-physiology-2e/pages/9-4-synovial-joints","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000010","topic_id":"e7301030-2026-4000-8001-000000000001","question_text":"Una zona duele a la palpación. ¿Qué conclusión es más adecuada?","explanation":"Un hallazgo palpatorio aislado no basta para identificar toda la causa del problema.","options":[{"text":"El dolor demuestra una lesión específica por sí solo","correct":false},{"text":"Integrar el hallazgo con historia, movimiento y otros datos","correct":true},{"text":"No hace falta entrevistar","correct":false},{"text":"Todos los tejidos vecinos están lesionados","correct":false}],"difficulty":2,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":10,"validation_status":"source_validated","is_published":true,"question_type":"clinical_case","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/9-1-classification-of-joints","https://openstax.org/books/anatomy-and-physiology-2e/pages/9-4-synovial-joints","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000011","topic_id":"e7301030-2026-4000-8001-000000000002","question_text":"¿Qué huesos forman la cintura escapular?","explanation":"La cintura escapular está formada por escápula y clavícula.","options":[{"text":"Radio y ulna","correct":false},{"text":"Escápula y clavícula","correct":true},{"text":"Húmero y radio exclusivamente","correct":false},{"text"