":null,"source_urls":["https://acsm.org/education-resources/books/guidelines-exercise-testing-prescription/","https://www.who.int/news-room/fact-sheets/detail/physical-activity","https://www.cdc.gov/physical-activity-basics/measuring/index.html","https://medlineplus.gov/ency/patientinstructions/000859.htm"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000146","topic_id":"e7301030-2026-4000-8001-000000000015","question_text":"¿Qué diferencia intensidad relativa de absoluta?","explanation":"Una misma actividad puede representar esfuerzos relativos distintos.","options":[{"text":"La relativa no depende nunca de condición física","correct":false},{"text":"La absoluta solo se mide con dolor","correct":false},{"text":"Ambas significan número de sesiones","correct":false},{"text":"La relativa considera el esfuerzo para esa persona","correct":true}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":6,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://acsm.org/education-resources/books/guidelines-exercise-testing-prescription/","https://www.who.int/news-room/fact-sheets/detail/physical-activity","https://www.cdc.gov/physical-activity-basics/measuring/index.html","https://medlineplus.gov/ency/patientinstructions/000859.htm"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000147","topic_id":"e7301030-2026-4000-8001-000000000015","question_text":"Dos personas caminan a igual velocidad, pero una se esfuerza mucho más. ¿Qué concepto lo explica?","explanation":"La capacidad individual modifica el esfuerzo relativo de la misma actividad.","options":[{"text":"Diferencia de intensidad relativa","correct":true},{"text":"Frecuencia idéntica implica esfuerzo idéntico","correct":false},{"text":"La duración deja de importar","correct":false},{"text":"Las preferencias prueban el esfuerzo","correct":false}],"difficulty":2,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":7,"validation_status":"source_validated","is_published":true,"question_type":"clinical_case","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://acsm.org/education-resources/books/guidelines-exercise-testing-prescription/","https://www.who.int/news-room/fact-sheets/detail/physical-activity","https://www.cdc.gov/physical-activity-basics/measuring/index.html","https://medlineplus.gov/ency/patientinstructions/000859.htm"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000148","topic_id":"e7301030-2026-4000-8001-000000000015","question_text":"¿Qué aporta registrar una medida inicial de la tarea?","explanation":"La referencia inicial facilita evaluar cambios y ajustar el plan.","options":[{"text":"Garantía de recuperación","correct":false},{"text":"Una referencia para comparar evolución","correct":true},{"text":"Una razón para omitir objetivos","correct":false},{"text":"El resultado final antes de intervenir","correct":false}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":8,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://acsm.org/education-resources/books/guidelines-exercise-testing-prescription/","https://www.who.int/news-room/fact-sheets/detail/physical-activity","https://www.cdc.gov/physical-activity-basics/measuring/index.html","https://medlineplus.gov/ency/patientinstructions/000859.htm"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000149","topic_id":"e7301030-2026-4000-8001-000000000015","question_text":"¿Qué afirmación sobre recomendaciones poblacionales es correcta?","explanation":"La rehabilitación necesita adaptar objetivos y cargas a la situación.","options":[{"text":"Sirven como dosis idéntica para toda lesión","correct":false},{"text":"Eliminan la necesidad de valoración","correct":false},{"text":"No sustituyen una prescripción individual de rehabilitación","correct":true},{"text":"Se aplican sin considerar limitaciones","correct":false}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":9,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://acsm.org/education-resources/books/guidelines-exercise-testing-prescription/","https://www.who.int/news-room/fact-sheets/detail/physical-activity","https://www.cdc.gov/physical-activity-basics/measuring/index.html","https://medlineplus.gov/ency/patientinstructions/000859.htm"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000150","topic_id":"e7301030-2026-4000-8001-000000000015","question_text":"Se cambia a la vez frecuencia, duración e intensidad y aparecen dificultades. ¿Qué faltó controlar mejor?","explanation":"Modificar varias demandas simultáneamente dificulta interpretar tolerancia y ajustar.","options":[{"text":"Solo el nombre comercial del material","correct":false},{"text":"Solo la decoración del centro","correct":false},{"text":"Solo la etiqueta del plan","correct":false},{"text":"La progresión y la respuesta a los cambios de carga","correct":true}],"difficulty":2,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":10,"validation_status":"source_validated","is_published":true,"question_type":"clinical_case","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://acsm.org/education-resources/books/guidelines-exercise-testing-prescription/","https://www.who.int/news-room/fact-sheets/detail/physical-activity","https://www.cdc.gov/physical-activity-basics/measuring/index.html","https://medlineplus.gov/ency/patientinstructions/000859.htm"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000151","topic_id":"e7301030-2026-4000-8001-000000000016","question_text":"¿Qué factor puede aumentar riesgo de lesión por ejercicio?","explanation":"La progresión excesivamente rápida figura entre los factores de riesgo evitables.","options":[{"text":"Aprender la técnica","correct":false},{"text":"Revisar el material","correct":false},{"text":"Adaptar la actividad","correct":false},{"text":"Aumentar la carga demasiado rápido","correct":true}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":1,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://medlineplus.gov/ency/patientinstructions/000859.htm","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000152","topic_id":"e7301030-2026-4000-8001-000000000016","question_text":"¿Qué conviene verificar del material?","explanation":"El ajuste, el estado y el uso del material influyen en la seguridad.","options":[{"text":"Que sea adecuado, esté en buen estado y se use correctamente","correct":true},{"text":"Solo su color","correct":false},{"text":"Solo su precio","correct":false},{"text":"Solo que sea nuevo","correct":false}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":2,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://medlineplus.gov/ency/patientinstructions/000859.htm","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000153","topic_id":"e7301030-2026-4000-8001-000000000016","question_text":"¿Qué criterio favorece una progresión interpretable?","explanation":"Controlar variables permite relacionar cambios de carga y tolerancia.","options":[{"text":"Aumentar todas las variables siempre","correct":false},{"text":"Controlar cambios de frecuencia, duración e intensidad","correct":true},{"text":"Ignorar respuesta posterior","correct":false},{"text":"Eliminar todo descanso","correct":false}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":3,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://medlineplus.gov/ency/patientinstructions/000859.htm","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000154","topic_id":"e7301030-2026-4000-8001-000000000016","question_text":"¿Qué indica el calentamiento progresivo en este contexto?","explanation":"El calentamiento es una medida preparatoria, no una garantía absoluta.","options":[{"text":"Garantizar que ninguna lesión es posible","correct":false},{"text":"Sustituir toda técnica","correct":false},{"text":"Preparar la actividad con una entrada gradual","correct":true},{"text":"Empezar directamente al máximo","correct":false}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":4,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://medlineplus.gov/ency/patientinstructions/000859.htm","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000155","topic_id":"e7301030-2026-4000-8001-000000000016","question_text":"Una persona presenta dolor torácico durante ejercicio. ¿Qué actuación es adecuada?","explanation":"El dolor torácico durante o después de ejercicio requiere valoración urgente.","options":[{"text":"Continuar para completar repeticiones","correct":false},{"text":"Aumentar intensidad","correct":false},{"text":"Atribuirlo siempre a falta de motivación","correct":false},{"text":"Detener y buscar atención urgente","correct":true}],"difficulty":2,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":5,"validation_status":"source_validated","is_published":true,"question_type":"clinical_case","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://medlineplus.gov/ency/patientinstructions/000859.htm","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000156","topic_id":"e7301030-2026-4000-8001-000000000016","question_text":"¿Qué debe hacerse ante dolor importante o una lesión durante la tarea?","explanation":"Un síntoma preocupante obliga a revisar la actividad y la necesidad de atención.","options":[{"text":"Detener y reevaluar, solicitando valoración según la situación","correct":true},{"text":"Ignorar el síntoma","correct":false},{"text":"Aplicar siempre más carga","correct":false},{"text":"Considerarlo prueba de eficacia","correct":false}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":6,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://medlineplus.gov/ency/patientinstructions/000859.htm","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000157","topic_id":"e7301030-2026-4000-8001-000000000016","question_text":"¿Qué problema tiene la regla «si duele, siempre funciona mejor»?","explanation":"El dolor no demuestra por sí solo eficacia y puede exigir detener o adaptar.","options":[{"text":"Es una ley física demostrada","correct":false},{"text":"No es un criterio de seguridad ni de eficacia","correct":true},{"text":"Permite omitir toda valoración","correct":false},{"text":"Sustituye todos los objetivos","correct":false}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":7,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://medlineplus.gov/ency/patientinstructions/000859.htm","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000158","topic_id":"e7301030-2026-4000-8001-000000000016","question_text":"¿Qué puede sugerir fatiga persistente entre sesiones?","explanation":"La fatiga persistente es un dato que debe integrarse en la revisión del plan.","options":[{"text":"Progreso óptimo en todos los casos","correct":false},{"text":"Que el descanso nunca importa","correct":false},{"text":"Necesidad de revisar carga y recuperación","correct":true},{"text":"Que toda fatiga significa una lesión concreta","correct":false}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":8,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://medlineplus.gov/ency/patientinstructions/000859.htm","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000159","topic_id":"e7301030-2026-4000-8001-000000000016","question_text":"¿Por qué se revisa el entorno antes de una tarea de equilibrio?","explanation":"La seguridad depende también del espacio, apoyos y supervisión.","options":[{"text":"Para eliminar toda necesidad de observar","correct":false},{"text":"Para dificultarla sin informar","correct":false},{"text":"Para sustituir la capacidad de la persona","correct":false},{"text":"Para reducir obstáculos y disponer de apoyo o supervisión adecuados","correct":true}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":9,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://medlineplus.gov/ency/patientinstructions/000859.htm","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000160","topic_id":"e7301030-2026-4000-8001-000000000016","question_text":"La persona toleró la sesión, pero describe problemas importantes después. ¿Qué corresponde?","explanation":"La respuesta posterior también informa sobre tolerancia y dosificación.","options":[{"text":"Recoger esa respuesta y revisar la planificación","correct":true},{"text":"Ignorarla porque ya terminó","correct":false},{"text":"Repetir sin cambios obligatoriamente","correct":false},{"text":"Afirmar recuperación sin escuchar","correct":false}],"difficulty":2,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":10,"validation_status":"source_validated","is_published":true,"question_type":"clinical_case","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://medlineplus.gov/ency/patientinstructions/000859.htm","https://www.nhs.uk/conditions/physiotherapy/"],"source_checked_at":"2026-10-30","official_exam":false,"teacher_review":"pending"}},{"id":"e7301030-2026-4000-8003-000000000161","topic_id":"e7301030-2026-4000-8001-000000000017","question_text":"¿Qué capacidad se relaciona con producir fuerza contra una resistencia?","explanation":"El fortalecimiento busca mejorar la capacidad de generar fuerza según objetivos.","options":[{"text":"Fuerza muscular","correct":true},{"text":"Visión de color","correct":false},{"text":"Memoria semántica exclusivamente","correct":false},{"text":"Audición","correct":false}],"difficulty":1,"source_label":"Entrenamiento original · fuentes institucionales consultadas · S2","display_order":1,"validation_status":"source_validated","is_published":true,"question_type":"mcq","accepted_answers":[],"metadata":{"batch":"es-s2-20261030","language":"es","translation_language":null,"source_urls":["https://www.who.int/news-room/fact-sheets/detail/physical-activity","https://www.cdc.gov/physical-activity-basics/measuring/index.html","https://www.nhs.uk/conditions/physiotherapy/","https://openstax.org/books/anatomy-and-physiology-2e/pages/14-1-sensory-p