UPDATE public.curriculum_quiz_questions SET question_text='¿Qué sistema nervioso se estudia expresamente en Anatomía II?',options='[{"text":"Sistema nervioso periférico","correct":true},{"text":"Solo el sistema endocrino","correct":false},{"text":"Solo el sistema digestivo","correct":false},{"text":"Ningún sistema nervioso","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Sistema nervioso periférico». Anatomía II incluye estructuras del sistema nervioso periférico.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='16aa6922-6358-4ad9-b986-5405734a2717'::uuid AND question_text='Quel système nerveux est explicitement étudié dans Anatomía II ?' AND options='[{"text":"Sistema nervioso periférico","correct":true},{"text":"Uniquement le système endocrinien","correct":false},{"text":"Uniquement le système digestif","correct":false},{"text":"Aucun système nerveux","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Cuál es uno de los ejes de Anatomía II?',options='[{"text":"Sistema musculoesquelético","correct":true},{"text":"Sistema endocrino únicamente","correct":false},{"text":"Nutrición clínica","correct":false},{"text":"Microbiología","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Sistema musculoesquelético». El programa aborda el aparato locomotor y sus relaciones funcionales.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='ec94e06c-4879-4566-b9f6-3942cc39c486'::uuid AND question_text='Quel est l’un des axes principaux d’Anatomía II ?' AND options='[{"text":"Sistema musculoesquelético","correct":true},{"text":"Sistema endocrino únicamente","correct":false},{"text":"Nutrición clínica","correct":false},{"text":"Microbiología","correct":false}]'::jsonb;
