UPDATE public.curriculum_quiz_questions SET question_text='¿Qué objetivo corresponde al bloque de biomecánica?',options='[{"text":"Conocer fundamentos mecánicos del movimiento humano","correct":true},{"text":"Aprender solo terminología administrativa","correct":false},{"text":"Estudiar únicamente células sanguíneas","correct":false},{"text":"Memorizar únicamente fármacos","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Conocer fundamentos mecánicos del movimiento humano». La biomecánica aplica fundamentos mecánicos al movimiento humano.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='4623b5b9-1843-4890-b42b-547bcbaab503'::uuid AND question_text='Quel est l’objectif du bloc de biomecánica ?' AND options='[{"text":"Conocer fundamentos mecánicos del movimiento humano","correct":true},{"text":"Aprender solo terminología administrativa","correct":false},{"text":"Estudiar únicamente células sanguíneas","correct":false},{"text":"Memorizar únicamente fármacos","correct":false}]'::jsonb;
