UPDATE public.curriculum_quiz_questions SET question_text='¿Cuáles son los dos grandes bloques de Biofísica y Biomecánica?',options='[{"text":"Biofísica y biomecánica","correct":true},{"text":"Histología y farmacología","correct":false},{"text":"Anatomía y psicología","correct":false},{"text":"Neurología y pediatría","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Biofísica y biomecánica». La asignatura reúne biofísica y biomecánica.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='2caccde5-3641-4231-a9b2-6a5fe241a933'::uuid AND question_text='Quels sont les deux grands blocs de l’UE Biofísica y Biomecánica ?' AND options='[{"text":"Biofísica y biomecánica","correct":true},{"text":"Histología y farmacología","correct":false},{"text":"Anatomía y psicología","correct":false},{"text":"Neurología y pediatría","correct":false}]'::jsonb;
