UPDATE public.curriculum_quiz_questions SET question_text='¿Qué tema pertenece al bloque de biofísica del plan UVic?',options='[{"text":"Electricidad","correct":true},{"text":"Farmacología clínica","correct":false},{"text":"Cirugía digestiva","correct":false},{"text":"Genética molecular avanzada","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Electricidad». El programa incluye electricidad, magnetismo, calor y ondas.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='2cd4a5db-b93c-410b-ad56-66d719de8f5f'::uuid AND question_text='Quel thème fait explicitement partie du bloc de biofísica à l’UVic ?' AND options='[{"text":"Electricidad","correct":true},{"text":"Farmacología clínica","correct":false},{"text":"Cirugía digestiva","correct":false},{"text":"Genética molecular avanzada","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Qué capacidad se trabaja especialmente al mantenerse de pie sobre una pierna?',options='[{"text":"Equilibrio","correct":true},{"text":"Solo resistencia respiratoria","correct":false},{"text":"Flexibilidad de los dedos","correct":false},{"text":"Solo fuerza de prensión","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Equilibrio». La tarea exige mantener estabilidad con una base de apoyo reducida.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='3d826190-2cd8-498f-9af2-2a5b3cdf7485'::uuid AND question_text='Quelle capacité est particulièrement sollicitée par « mantenerse de pie sobre una pierna » ?' AND options='[{"text":"Équilibre","correct":true},{"text":"Endurance respiratoire uniquement","correct":false},{"text":"Souplesse des doigts","correct":false},{"text":"Force de préhension uniquement","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Cuál es un ejemplo de actividad aeróbica?',options='[{"text":"Caminar","correct":true},{"text":"Mantener solo una postura estática","correct":false},{"text":"Hacer solo una contracción isométrica de mano","correct":false},{"text":"Permanecer sentado sin moverse","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Caminar». Caminar puede ser una actividad aeróbica según intensidad y condiciones.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='d2b85638-1f75-404a-b388-9b61fc975ee7'::uuid AND question_text='Quel exercice est un exemple d’activité aérobie ?' AND options='[{"text":"Caminar","correct":true},{"text":"Maintenir uniquement une posture statique","correct":false},{"text":"Faire uniquement une contraction isométrique de la main","correct":false},{"text":"Rester assis sans bouger","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Vocabulario FR/ES — ¿Cómo se dice «flexibilité» en español?',options='[{"text":"flexibilidad","correct":true},{"text":"fuerza","correct":false},{"text":"resistencia","correct":false},{"text":"equilibrio","correct":false}]'::jsonb,explanation='Ejercicio bilingüe explícito de vocabulario FR/ES. El equivalente aceptado es «flexibilidad».',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es-fr","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='7fb6a653-445b-4fcb-b3d4-c06678655c90'::uuid AND question_text='Comment dit-on « flexibilité » en espagnol ?' AND options='[{"text":"flexibilidad","correct":true},{"text":"fuerza","correct":false},{"text":"resistencia","correct":false},{"text":"equilibrio","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Qué capacidades pueden trabajar los ejercicios de equilibrio?',options='[{"text":"Mejoran estabilidad y coordinación","correct":true},{"text":"Solo aumentan la frecuencia cardíaca","correct":false},{"text":"Sustituyen todo trabajo de fuerza","correct":false},{"text":"Solo sirven para estirar músculos","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Mejoran estabilidad y coordinación». Las tareas de equilibrio pueden trabajar estabilidad y coordinación.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='2ab97e66-7e2b-4313-afdb-4c8b32e401b5'::uuid AND question_text='Quel effet principal ont les exercices d’équilibre selon MedlinePlus ?' AND options='[{"text":"Ils améliorent stabilité et coordination","correct":true},{"text":"Ils augmentent uniquement la fréquence cardiaque","correct":false},{"text":"Ils remplacent tout travail de force","correct":false},{"text":"Ils servent uniquement à étirer les muscles","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Vocabulario FR/ES — ¿Cuál es el equivalente francés de «resistencia cardiovascular»?',options='[{"text":"Endurance cardiovasculaire","correct":true},{"text":"Force maximale","correct":false},{"text":"Souplesse","correct":false},{"text":"Douleur articulaire","correct":false}]'::jsonb,explanation='Ejercicio bilingüe explícito de vocabulario FR/ES. El equivalente aceptado es «Endurance cardiovasculaire».',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es-fr","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='6a6c59a0-1267-43a8-95a0-9241e9760e63'::uuid AND question_text='Que signifie « resistencia cardiovascular » en français ?' AND options='[{"text":"Endurance cardiovasculaire","correct":true},{"text":"Force maximale","correct":false},{"text":"Souplesse","correct":false},{"text":"Douleur articulaire","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Qué tipo de actividad corresponde a ejercicios de fuerza?',options='[{"text":"Ejercicios de fortalecimiento muscular","correct":true},{"text":"Solo ejercicios respiratorios","correct":false},{"text":"Solo estiramientos pasivos","correct":false},{"text":"Solo relajación","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Ejercicios de fortalecimiento muscular». El trabajo de fuerza incluye resistencia externa o peso corporal, adaptados al objetivo.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='1dfe934d-d6a5-4e9f-bee2-4cfab0db92da'::uuid AND question_text='Quel type d’exercice correspond à « ejercicios de fuerza » ?' AND options='[{"text":"Des exercices de renforcement musculaire","correct":true},{"text":"Uniquement des exercices respiratoires","correct":false},{"text":"Uniquement des étirements passifs","correct":false},{"text":"Uniquement de la relaxation","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Vocabulario FR/ES — ¿Cuál es la traducción francesa de «parar el ejercicio»?',options='[{"text":"Arrêter l’exercice","correct":true},{"text":"Répéter l’exercice","correct":false},{"text":"Accélérer l’exercice","correct":false},{"text":"Mesurer l’exercice","correct":false}]'::jsonb,explanation='Ejercicio bilingüe explícito de vocabulario FR/ES. El equivalente aceptado es «Arrêter l’exercice».',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es-fr","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='65156ec5-bc7f-428d-9f5c-c3ec956d87d6'::uuid AND question_text='Que signifie « parar el ejercicio » en français ?' AND options='[{"text":"Arrêter l’exercice","correct":true},{"text":"Répéter l’exercice","correct":false},{"text":"Accélérer l’exercice","correct":false},{"text":"Mesurer l’exercice","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Qué síntoma respiratorio requiere detener el ejercicio?',options='[{"text":"Dificultad para respirar extrema","correct":true},{"text":"Respiración normal tras el esfuerzo","correct":false},{"text":"Ligera sensación de calor","correct":false},{"text":"Sudoración moderada aislada","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Dificultad para respirar extrema». Una dificultad respiratoria extrema exige detener la tarea y valoración apropiada.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='6c460941-bd6e-49eb-98f2-1cebd173709a'::uuid AND question_text='Quel signe respiratoire impose d’arrêter l’exercice selon MedlinePlus ?' AND options='[{"text":"Dificultad para respirar extrema","correct":true},{"text":"Respiration normale après l’effort","correct":false},{"text":"Légère sensation de chaleur","correct":false},{"text":"Transpiration modérée isolée","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Qué principio de progresión es adecuado al retomar actividad?',options='[{"text":"Aumentar gradualmente la actividad","correct":true},{"text":"Empezar directamente a intensidad máxima","correct":false},{"text":"No modificar nunca la intensidad","correct":false},{"text":"Evitar toda actividad regular","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Aumentar gradualmente la actividad». La carga debe adaptarse de forma gradual y según respuesta.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='db13eb59-f392-4a62-a8cd-b54e7112069c'::uuid AND question_text='Quelle progression est recommandée lorsqu’on reprend l’activité ?' AND options='[{"text":"Augmenter progressivement l’activité","correct":true},{"text":"Commencer directement à intensité maximale","correct":false},{"text":"Ne jamais modifier l’intensité","correct":false},{"text":"Éviter toute activité régulière","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Vocabulario FR/ES — ¿Cuál es el equivalente francés de «mareos»?',options='[{"text":"Vertiges / étourdissements","correct":true},{"text":"Crampes","correct":false},{"text":"Raideur","correct":false},{"text":"Faiblesse musculaire","correct":false}]'::jsonb,explanation='Ejercicio bilingüe explícito de vocabulario FR/ES. El equivalente aceptado es «Vertiges / étourdissements».',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es-fr","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='6f908caa-de50-4143-84fc-f1f43804aae0'::uuid AND question_text='Que signifie « mareos » en français ?' AND options='[{"text":"Vertiges / étourdissements","correct":true},{"text":"Crampes","correct":false},{"text":"Raideur","correct":false},{"text":"Faiblesse musculaire","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Vocabulario FR/ES — En una consulta, ¿cómo se traduce «ejercicio terapéutico» al francés?',options='[{"text":"Exercice thérapeutique","correct":true},{"text":"Examen radiologique","correct":false},{"text":"Traitement médicamenteux","correct":false},{"text":"Repos absolu","correct":false}]'::jsonb,explanation='Ejercicio bilingüe explícito de vocabulario FR/ES. El equivalente aceptado es «Exercice thérapeutique».',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es-fr","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='0bd74a96-40ac-4477-b383-de5575803939'::uuid AND question_text='Caso: que signifie « ejercicio terapéutico » en français ?' AND options='[{"text":"Exercice thérapeutique","correct":true},{"text":"Examen radiologique","correct":false},{"text":"Traitement médicamenteux","correct":false},{"text":"Repos absolu","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Caso — Durante el ejercicio, la persona dice «Me mareo». ¿Qué actuación es la más adecuada?',options='[{"text":"Parar el ejercicio","correct":true},{"text":"Aumentar la intensidad","correct":false},{"text":"Ignorar el síntoma","correct":false},{"text":"Pedirle que corra","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Parar el ejercicio». El mareo requiere detener, proteger de caídas y valorar la situación.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='58d39f94-4822-4c1b-ad13-102109724a72'::uuid AND question_text='Caso: pendant l’exercice, le patient dit « Me mareo ». Quelle est la bonne réaction ?' AND options='[{"text":"Parar el ejercicio","correct":true},{"text":"Aumentar la intensidad","correct":false},{"text":"Ignorar el síntoma","correct":false},{"text":"Pedirle que corra","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Caso — La persona muestra inestabilidad en una superficie irregular. ¿Qué capacidades conviene incluir en la valoración y el trabajo funcional?',options='[{"text":"Equilibrio y coordinación","correct":true},{"text":"Solo flexibilidad cervical","correct":false},{"text":"Solo fuerza de mano","correct":false},{"text":"Solo respiración","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Equilibrio y coordinación». La inestabilidad debe explorarse con otros datos antes de atribuir una causa.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='77fe2299-1692-4d49-ae5f-deca9ec00734'::uuid AND question_text='Caso: le patient est instable sur un sol irrégulier. Quelle capacité faut-il prioritairement travailler ?' AND options='[{"text":"Equilibrio y coordinación","correct":true},{"text":"Solo flexibilidad cervical","correct":false},{"text":"Solo fuerza de mano","correct":false},{"text":"Solo respiración","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Caso — El objetivo es mejorar tolerancia al caminar. ¿Qué categoría de ejercicio es coherente?',options='[{"text":"Ejercicio aeróbico / cardiovascular","correct":true},{"text":"Únicamente fuerza de prensión","correct":false},{"text":"Únicamente movilidad de dedos","correct":false},{"text":"Reposo completo sistemático","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Ejercicio aeróbico / cardiovascular». Un objetivo de tolerancia a la marcha se relaciona con trabajo cardiovascular adaptado.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='220e06c2-1b48-4c02-9fc0-7e582ce3aaa7'::uuid AND question_text='Caso: l’objectif est d’améliorer l’endurance à la marche. Quelle catégorie d’exercice est la plus cohérente ?' AND options='[{"text":"Ejercicio aeróbico / cardiovascular","correct":true},{"text":"Únicamente fuerza de prensión","correct":false},{"text":"Únicamente movilidad de dedos","correct":false},{"text":"Repos complet systématique","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Caso — Se identifica falta de fuerza al levantarse de una silla. ¿Qué categoría de ejercicio puede ser pertinente?',options='[{"text":"Ejercicio de fuerza","correct":true},{"text":"Solo relajación","correct":false},{"text":"Solo estiramiento pasivo","correct":false},{"text":"Solo respiración tranquila","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Ejercicio de fuerza». La falta de fuerza puede abordarse con fortalecimiento según la valoración.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='993aec46-5123-4ed9-9037-39edd4867f66'::uuid AND question_text='Caso: un patient manque de force pour se relever d’une chaise. Quel type d’exercice correspond le mieux à cet objectif de base ?' AND options='[{"text":"Ejercicio de fuerza","correct":true},{"text":"Solo relajación","correct":false},{"text":"Solo estiramiento pasivo","correct":false},{"text":"Solo respiración tranquila","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Vocabulario FR/ES — ¿Cuál es el equivalente francés de «pierna débil»?',options='[{"text":"Jambe faible","correct":true},{"text":"Jambe douloureuse uniquement","correct":false},{"text":"Jambe opérée obligatoirement","correct":false},{"text":"Jambe saine","correct":false}]'::jsonb,explanation='Ejercicio bilingüe explícito de vocabulario FR/ES. El equivalente aceptado es «Jambe faible».',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es-fr","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='0e61dc1e-1262-4820-9309-d9a2bd9ad7be'::uuid AND question_text='Que signifie « pierna débil » ?' AND options='[{"text":"Jambe faible","correct":true},{"text":"Jambe douloureuse uniquement","correct":false},{"text":"Jambe opérée obligatoirement","correct":false},{"text":"Jambe saine","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='En la secuencia de marcha con caminador descrita por MedlinePlus, ¿qué pierna avanza primero?',options='[{"text":"La pierna débil","correct":true},{"text":"Solo la pierna fuerte","correct":false},{"text":"Las dos piernas a la vez","correct":false},{"text":"No se indica ninguna secuencia","correct":false}]'::jsonb,explanation='La respuesta adecuada es «La pierna débil». Esta es la secuencia descrita por la fuente para el uso indicado; no es una regla para cualquier ayuda.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='e4c1d02b-ecb7-4eb6-a4ae-aa2cc0bfe4d5'::uuid AND question_text='Quelle jambe avance en premier avec un déambulateur selon les instructions MedlinePlus ?' AND options='[{"text":"La jambe faible","correct":true},{"text":"La jambe forte uniquement","correct":false},{"text":"Les deux jambes en même temps","correct":false},{"text":"Aucune règle n’est donnée","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Vocabulario FR/ES — Completa en francés: «muletas» = ___.',options='[]'::jsonb,explanation='Ejercicio bilingüe explícito de vocabulario FR/ES. El equivalente aceptado es «béquilles».',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es-fr","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='0d8a5b27-ec36-405e-8716-a61174f3280d'::uuid AND question_text='ES → FR — Complète : « muletas » = ___' AND options='[]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Qué tres variables se recomienda evitar aumentar simultáneamente al progresar ejercicio?',options='[{"text":"Frecuencia, duración e intensidad","correct":true},{"text":"Peso, talla y edad","correct":false},{"text":"Dolor, sueño y alimentación","correct":false},{"text":"Fuerza, equilibrio y movilidad","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Frecuencia, duración e intensidad». Modificar varias demandas a la vez dificulta interpretar la tolerancia.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='8933fbef-bb8b-441f-8358-5d41dfe8e5f1'::uuid AND question_text='Quels trois paramètres MedlinePlus déconseille-t-il d’augmenter simultanément ?' AND options='[{"text":"Fréquence, durée et intensité","correct":true},{"text":"Poids, taille et âge","correct":false},{"text":"Douleur, sommeil et alimentation","correct":false},{"text":"Force, équilibre et mobilité","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Qué principio favorece una progresión segura al inicio?',options='[{"text":"Aumentar gradualmente","correct":true},{"text":"Aumentar bruscamente la intensidad","correct":false},{"text":"Duplicar cada sesión","correct":false},{"text":"Ignorar la fatiga","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Aumentar gradualmente». Una progresión gradual facilita adaptar carga y respuesta.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='a08814d6-0321-42ce-b75f-5b4a8f22e107'::uuid AND question_text='Quelle progression est la plus sûre au début ?' AND options='[{"text":"Augmenter progressivement","correct":true},{"text":"Augmenter brutalement l’intensité","correct":false},{"text":"Doubler chaque séance","correct":false},{"text":"Ignorer la fatigue","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Vocabulario FR/ES — ¿Qué frase española corresponde a «Progressez lentement»?',options='[{"text":"Progrese lentamente","correct":true},{"text":"Corra más rápido","correct":false},{"text":"No descanse nunca","correct":false},{"text":"Aumente todo a la vez","correct":false}]'::jsonb,explanation='Ejercicio bilingüe explícito de vocabulario FR/ES. El equivalente aceptado es «Progrese lentamente».',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es-fr","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='79a13a45-758e-48af-a9f3-68899c6e99d1'::uuid AND question_text='Quelle phrase espagnole correspond à « Progressez lentement » ?' AND options='[{"text":"Progrese lentamente","correct":true},{"text":"Corra más rápido","correct":false},{"text":"No descanse nunca","correct":false},{"text":"Aumente todo a la vez","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Cuál es un objetivo general de la rehabilitación?',options='[{"text":"Recuperar, mantener o mejorar capacidades útiles para la vida diaria","correct":true},{"text":"Suprimir todo movimiento","correct":false},{"text":"Sustituir todas las actividades por reposo","correct":false},{"text":"Centrarse solo en dolor","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Recuperar, mantener o mejorar capacidades útiles para la vida diaria». La rehabilitación se orienta a capacidades relevantes para la vida de la persona.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='8d4630c7-84de-4888-9f99-66646ffe6d18'::uuid AND question_text='Quel est l’objectif général de la réadaptation selon MedlinePlus ?' AND options='[{"text":"Récupérer, maintenir ou améliorer les capacités utiles à la vie quotidienne","correct":true},{"text":"Supprimer tout mouvement","correct":false},{"text":"Remplacer toutes les activités par du repos","correct":false},{"text":"Se concentrer uniquement sur la douleur","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Caso — La persona tiene dificultad para levantarse y caminar. ¿Qué ámbito funcional se describe?',options='[{"text":"Movilidad funcional","correct":true},{"text":"Visión","correct":false},{"text":"Audición","correct":false},{"text":"Función digestiva","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Movilidad funcional». Levantarse y caminar son tareas de movilidad funcional.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='bda22062-f574-409f-a811-29cae9b8c6b8'::uuid AND question_text='Un patient a du mal à se lever d’une chaise et à marcher. À quel domaine cela se rattache-t-il le plus directement ?' AND options='[{"text":"Mobilité fonctionnelle","correct":true},{"text":"Vision","correct":false},{"text":"Audition","correct":false},{"text":"Fonction digestive","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Vocabulario FR/ES — ¿Cómo se traduce «actividades de la vida diaria» al francés?',options='[{"text":"Activités de la vie quotidienne","correct":true},{"text":"Activités sportives de haut niveau","correct":false},{"text":"Examens radiologiques","correct":false},{"text":"Traitements médicamenteux","correct":false}]'::jsonb,explanation='Ejercicio bilingüe explícito de vocabulario FR/ES. El equivalente aceptado es «Activités de la vie quotidienne».',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es-fr","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='8edbde12-7c91-4fcc-adb7-0307d796e4b4'::uuid AND question_text='Que signifie « actividades de la vida diaria » ?' AND options='[{"text":"Activités de la vie quotidienne","correct":true},{"text":"Activités sportives de haut niveau","correct":false},{"text":"Examens radiologiques","correct":false},{"text":"Traitements médicamenteux","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Qué síntoma durante el ejercicio exige detener y reevaluar?',options='[{"text":"Mareos","correct":true},{"text":"Respiración tranquila","correct":false},{"text":"Buena tolerancia","correct":false},{"text":"Comodidad estable","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Mareos». Un síntoma como mareo requiere detener y reevaluar con seguridad.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='900bb562-a71e-488d-9983-a3bcbe57b7b7'::uuid AND question_text='Quel signe pendant un exercice impose de s’arrêter selon MedlinePlus ?' AND options='[{"text":"Vertiges","correct":true},{"text":"Respiration calme","correct":false},{"text":"Bonne tolérance","correct":false},{"text":"Confort stable","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Qué recurso puede valorarse cuando caminar resulta difícil?',options='[{"text":"Una ayuda para caminar","correct":true},{"text":"Reposo sistemático en cama","correct":false},{"text":"Ninguna adaptación","correct":false},{"text":"Ejercicio doloroso impuesto","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Una ayuda para caminar». La selección y ajuste de una ayuda requieren valorar necesidades y seguridad.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='257fb664-2fb2-4b5a-97e1-009ab8e0cbee'::uuid AND question_text='Quelle aide peut être envisagée si la marche est difficile ?' AND options='[{"text":"Une aide à la marche","correct":true},{"text":"Un repos au lit systématique","correct":false},{"text":"Aucune adaptation","correct":false},{"text":"Un exercice douloureux imposé","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Vocabulario FR/ES — ¿Cuál es la traducción francesa de «riesgo de caída»?',options='[{"text":"Risque de chute","correct":true},{"text":"Risque infectieux","correct":false},{"text":"Douleur musculaire","correct":false},{"text":"Amplitude articulaire","correct":false}]'::jsonb,explanation='Ejercicio bilingüe explícito de vocabulario FR/ES. El equivalente aceptado es «Risque de chute».',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es-fr","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='e6fa92e4-fa8b-4635-b973-b523a04dc3da'::uuid AND question_text='Que signifie « riesgo de caída » en français ?' AND options='[{"text":"Risque de chute","correct":true},{"text":"Risque infectieux","correct":false},{"text":"Douleur musculaire","correct":false},{"text":"Amplitude articulaire","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Qué puede observarse en una valoración funcional básica?',options='[{"text":"Marcha, equilibrio y coordinación","correct":true},{"text":"Solo el color de la ropa","correct":false},{"text":"Solo la talla","correct":false},{"text":"Solo el peso de la mochila","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Marcha, equilibrio y coordinación». Observar tareas aporta información de estabilidad, coordinación y desplazamiento.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='df2ebf0e-1d07-4b6c-9109-6a1457841ec4'::uuid AND question_text='Dans une observation fonctionnelle simple, que peut-on regarder en priorité ?' AND options='[{"text":"Marche, équilibre et coordination","correct":true},{"text":"Uniquement la couleur des vêtements","correct":false},{"text":"Uniquement la taille","correct":false},{"text":"Uniquement le poids du sac","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Qué movimientos es pertinente observar al valorar funcionalmente el hombro?',options='[{"text":"Movimiento del hombro y de la escápula","correct":true},{"text":"Solo temperatura corporal","correct":false},{"text":"Solo visión","correct":false},{"text":"Solo pulso radial","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Movimiento del hombro y de la escápula». La coordinación entre hombro y escápula es relevante para elevar el brazo.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='848f0846-6c22-4fe5-be5a-c614a9d5eb5b'::uuid AND question_text='Lors d’une évaluation fonctionnelle simple de l’épaule, que peut-on observer ?' AND options='[{"text":"Le mouvement de l’épaule et de l’omoplate","correct":true},{"text":"Uniquement la température corporelle","correct":false},{"text":"Uniquement la vision","correct":false},{"text":"Uniquement le pouls radial","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Caso — Hay dolor, debilidad y rigidez de hombro. ¿Qué dominios de valoración son pertinentes?',options='[{"text":"Rango de movimiento + músculos débiles o rígidos + movimientos dolorosos","correct":true},{"text":"Solo talla de la persona","correct":false},{"text":"Solo presión arterial","correct":false},{"text":"Solo color de piel","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Rango de movimiento + músculos débiles o rígidos + movimientos dolorosos». Conviene distinguir dolor, movilidad y fuerza en lugar de asumir una sola causa.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='4b8011ac-4244-47da-a9e7-5f9c30c989a7'::uuid AND question_text='Un patient a douleur, faiblesse et raideur de l’épaule. Quelle évaluation est pertinente ?' AND options='[{"text":"Rango de movimiento + músculos débiles o rígidos + movimientos dolorosos","correct":true},{"text":"Uniquement la taille du patient","correct":false},{"text":"Uniquement la tension artérielle","correct":false},{"text":"Uniquement la couleur de peau","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Vocabulario FR/ES — Completa en francés: «debilidad» = ___.',options='[]'::jsonb,explanation='Ejercicio bilingüe explícito de vocabulario FR/ES. El equivalente aceptado es «faiblesse».',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es-fr","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='9b60983d-33f8-468d-91fd-26138d5b356d'::uuid AND question_text='ES → FR — Complète : « debilidad » = ___' AND options='[]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Por qué es útil observar la tarea de sentarse y levantarse?',options='[{"text":"Combina fuerza, control y equilibrio","correct":true},{"text":"Evalúa únicamente la visión","correct":false},{"text":"Mide únicamente la flexibilidad de los dedos","correct":false},{"text":"No tiene relación con la función cotidiana","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Combina fuerza, control y equilibrio». Es una tarea cotidiana que integra fuerza, control y estabilidad.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='3c4f08b4-d892-4172-a7e0-864f2584ea04'::uuid AND question_text='Pourquoi le passage assis-debout est-il intéressant en évaluation fonctionnelle ?' AND options='[{"text":"Il combine force, contrôle et équilibre","correct":true},{"text":"Il teste uniquement la vision","correct":false},{"text":"Il mesure uniquement la souplesse des doigts","correct":false},{"text":"Il n’a aucun lien avec la fonction quotidienne","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Durante la tarea de sentarse y levantarse, ¿qué dato conviene registrar?',options='[{"text":"Uso de las manos, simetría y estabilidad","correct":true},{"text":"Solo frecuencia respiratoria en reposo","correct":false},{"text":"Solo movilidad de muñeca","correct":false},{"text":"Solo sensibilidad facial","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Uso de las manos, simetría y estabilidad». Los apoyos y compensaciones describen cómo se ejecuta la tarea.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='46f179a9-72f5-46d2-a972-b6d097fe6fa0'::uuid AND question_text='Lors d’un passage assis-debout, quel élément est utile à observer ?' AND options='[{"text":"Utilisation des mains, symétrie et stabilité","correct":true},{"text":"Uniquement le rythme respiratoire au repos","correct":false},{"text":"Uniquement la mobilité du poignet","correct":false},{"text":"Uniquement la sensibilité faciale","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Vocabulario FR/ES — ¿Cuál es el equivalente francés de «ponerse de pie»?',options='[{"text":"Se lever","correct":true},{"text":"S’allonger","correct":false},{"text":"Ramper","correct":false},{"text":"Tourner la tête","correct":false}]'::jsonb,explanation='Ejercicio bilingüe explícito de vocabulario FR/ES. El equivalente aceptado es «Se lever».',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es-fr","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='bf19fa9f-c8ef-4d7a-bf41-836cbddaee3a'::uuid AND question_text='Que signifie « ponerse de pie » ?' AND options='[{"text":"Se lever","correct":true},{"text":"S’allonger","correct":false},{"text":"Ramper","correct":false},{"text":"Tourner la tête","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Vocabulario FR/ES — Completa en español: «se relever» = ___.',options='[]'::jsonb,explanation='Ejercicio bilingüe explícito de vocabulario FR/ES. El equivalente aceptado es «levantarse».',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es-fr","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='ed616741-5251-434f-a694-24f06df7d529'::uuid AND question_text='FR → ES — Complète : « se relever » = ___' AND options='[]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Caso — La persona eleva el brazo con dificultad. ¿Qué información funcional conviene recoger?',options='[{"text":"Observar cómo realiza el movimiento y su limitación","correct":true},{"text":"Concluir inmediatamente una lesión concreta","correct":false},{"text":"Ignorar la función cotidiana","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Observar cómo realiza el movimiento y su limitación». La repercusión en movimiento y actividades orienta la valoración.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='0fd25aa0-b309-4e7e-b514-82564da71e8a'::uuid AND question_text='Un patient lève difficilement le bras. Quelle information est prioritaire pour le kiné ?' AND options='[{"text":"Observer comment le mouvement est réalisé et sa limitation","correct":true},{"text":"Conclure immédiatement à une lésion précise","correct":false},{"text":"Ignorer la fonction quotidienne","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Qué fase inicial sencilla forma parte de la exploración física?',options='[{"text":"La inspección","correct":true},{"text":"Prescripción farmacológica","correct":false},{"text":"Las pruebas de imagen","correct":false}]'::jsonb,explanation='La respuesta adecuada es «La inspección». La inspección permite observar antes de otras maniobras.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='a6c0b319-cb3b-418b-aca1-29b125437419'::uuid AND question_text='Quel est le premier temps simple de l’examen physique ?' AND options='[{"text":"L’inspection","correct":true},{"text":"La prescription médicamenteuse","correct":false},{"text":"L’imagerie","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Vocabulario FR/ES — ¿Cómo se interpreta «movilidad limitada» en francés?',options='[{"text":"Mobilité","correct":true},{"text":"Sensibilité","correct":false},{"text":"Endurance","correct":false}]'::jsonb,explanation='Ejercicio bilingüe explícito de vocabulario FR/ES. El equivalente aceptado es «Mobilité».',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es-fr","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='7cf0d20a-7a9a-44f7-8aec-cd4893d28f71'::uuid AND question_text='Dans un bilan fonctionnel, que signifie « movilidad limitada » ?' AND options='[{"text":"Mobilité","correct":true},{"text":"Sensibilité","correct":false},{"text":"Endurance","correct":false}]'::jsonb;
