UPDATE public.curriculum_quiz_questions SET question_text='¿Qué objetivo es más funcional para alguien que tiene dificultad al levantarse de una silla?',options='[{"text":"Levantarse de una silla con más facilidad y seguridad","correct":true},{"text":"Aprender el número de ECTS del programa","correct":false},{"text":"Memorizar únicamente el nombre de los músculos","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Levantarse de una silla con más facilidad y seguridad». El objetivo debe vincularse a una actividad concreta de la persona.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='cf089d29-c9f2-4f42-a3d2-0576e3bb62dd'::uuid AND question_text='Quel objectif est le plus fonctionnel pour un patient qui peine à se lever d’une chaise ?' AND options='[{"text":"Se lever d’une chaise plus facilement et en sécurité","correct":true},{"text":"Apprendre le nombre d’ECTS du cursus","correct":false},{"text":"Mémoriser uniquement le nom des muscles","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='¿Qué finalidad es central en rehabilitación?',options='[{"text":"Mejorar capacidades útiles para la vida diaria","correct":true},{"text":"Trabajar únicamente una estructura aislada","correct":false},{"text":"Evitar toda actividad funcional","correct":false}]'::jsonb,explanation='La respuesta adecuada es «Mejorar capacidades útiles para la vida diaria». La rehabilitación busca función y participación, no solo un síntoma aislado.',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='5a7268f2-09b8-422e-8078-dad5f87dafce'::uuid AND question_text='Quel est un objectif central de la réadaptation ?' AND options='[{"text":"Améliorer des capacités utiles à la vie quotidienne","correct":true},{"text":"Travailler uniquement une structure isolée","correct":false},{"text":"Éviter toute activité fonctionnelle","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Vocabulario FR/ES — Completa en español: «activité quotidienne» = ___.',options='[]'::jsonb,explanation='Ejercicio bilingüe explícito de vocabulario FR/ES. El equivalente aceptado es «actividad diaria».',metadata='{"difficulty_scale_version":"2026-10-v1","language_revision":"es-s2-20261030","language":"es-fr","editorial_revision_only":true}'::jsonb,updated_at=now() WHERE id='836bb93a-52c7-4efc-8edb-4e5cbd91f054'::uuid AND question_text='FR → ES — Complète : « activité quotidienne » = ___' AND options='[]'::jsonb;
DO $$ BEGIN IF (SELECT count(*) FROM public.curriculum_quiz_questions WHERE metadata->>'batch'='es-s2-20261030' AND is_published AND validation_status='source_validated')<>200 THEN RAISE EXCEPTION 'S2 count'; END IF; IF (SELECT count(*) FROM public.curriculum_quiz_questions WHERE metadata->>'language_revision'='es-s2-20261030')<>64 THEN RAISE EXCEPTION 'Legacy revision count'; END IF; END $$;
SELECT set_config('request.jwt.claim.sub',(SELECT pp.user_id::text FROM public.profile_programs pp JOIN public.profiles p ON p.id=pp.user_id WHERE pp.program_id='kineo-es' AND p.role<>'admin' AND coalesce(pp.curriculum_version,'default')='default' ORDER BY pp.created_at LIMIT 1),true);
SAVEPOINT scoring_checks;
SET LOCAL ROLE authenticated;
DO $$ DECLARE v jsonb; x jsonb; BEGIN
 IF (SELECT count(*) FROM public.curriculum_units WHERE id IN ('e7301030-2026-4000-8000-000000000001','e7301030-2026-4000-8000-000000000002','e7301030-2026-4000-8000-000000000003','e7301030-2026-4000-8000-000000000004','e7301030-2026-4000-8000-000000000005'))<>5 THEN RAISE EXCEPTION 'units RLS'; END IF;
 IF (SELECT count(*) FROM public.curriculum_lessons WHERE topic_id=ANY(ARRAY['e7301030-2026-4000-8001-000000000001'::uuid,'e7301030-2026-4000-8001-000000000002'::uuid,'e7301030-2026-4000-8001-000000000003'::uuid,'e7301030-2026-4000-8001-000000000004'::uuid,'e7301030-2026-4000-8001-000000000005'::uuid,'e7301030-2026-4000-8001-000000000006'::uuid,'e7301030-2026-4000-8001-000000000007'::uuid,'e7301030-2026-4000-8001-000000000008'::uuid,'e7301030-2026-4000-8001-000000000009'::uuid,'e7301030-2026-4000-8001-000000000010'::uuid,'e7301030-2026-4000-8001-000000000011'::uuid,'e7301030-2026-4000-8001-000000000012'::uuid,'e7301030-2026-4000-8001-000000000013'::uuid,'e7301030-2026-4000-8001-000000000014'::uuid,'e7301030-2026-4000-8001-000000000015'::uuid,'e7301030-2026-4000-8001-000000000016'::uuid,'e7301030-2026-4000-8001-000000000017'::uuid,'e7301030-2026-4000-8001-000000000018'::uuid,'e7301030-2026-4000-8001-000000000019'::uuid,'e7301030-2026-4000-8001-000000000020'::uuid]))<>20 THEN RAISE EXCEPTION 'lessons RLS'; END IF;
 IF (SELECT count(*) FROM public.get_curriculum_quiz_questions_v1(ARRAY['e7301030-2026-4000-8001-000000000001'::uuid,'e7301030-2026-4000-8001-000000000002'::uuid,'e7301030-2026-4000-8001-000000000003'::uuid,'e7301030-2026-4000-8001-000000000004'::uuid,'e7301030-2026-4000-8001-000000000005'::uuid,'e7301030-2026-4000-8001-000000000006'::uuid,'e7301030-2026-4000-8001-000000000007'::uuid,'e7301030-2026-4000-8001-000000000008'::uuid,'e7301030-2026-4000-8001-000000000009'::uuid,'e7301030-2026-4000-8001-000000000010'::uuid,'e7301030-2026-4000-8001-000000000011'::uuid,'e7301030-2026-4000-8001-000000000012'::uuid,'e7301030-2026-4000-8001-000000000013'::uuid,'e7301030-2026-4000-8001-000000000014'::uuid,'e7301030-2026-4000-8001-000000000015'::uuid,'e7301030-2026-4000-8001-000000000016'::uuid,'e7301030-2026-4000-8001-000000000017'::uuid,'e7301030-2026-4000-8001-000000000018'::uuid,'e7301030-2026-4000-8001-000000000019'::uuid,'e7301030-2026-4000-8001-000000000020'::uuid]))<>200 THEN RAISE EXCEPTION 'playable count'; END IF;
 IF EXISTS(SELECT 1 FROM public.get_curriculum_quiz_questions_v1(ARRAY['e7301030-2026-4000-8001-000000000001'::uuid,'e7301030-2026-4000-8001-000000000002'::uuid,'e7301030-2026-4000-8001-000000000003'::uuid,'e7301030-2026-4000-8001-000000000004'::uuid,'e7301030-2026-4000-8001-000000000005'::uuid,'e7301030-2026-4000-8001-000000000006'::uuid,'e7301030-2026-4000-8001-000000000007'::uuid,'e7301030-2026-4000-8001-000000000008'::uuid,'e7301030-2026-4000-8001-000000000009'::uuid,'e7301030-2026-4000-8001-000000000010'::uuid,'e7301030-2026-4000-8001-000000000011'::uuid,'e7301030-2026-4000-8001-000000000012'::uuid,'e7301030-2026-4000-8001-000000000013'::uuid,'e7301030-2026-4000-8001-000000000014'::uuid,'e7301030-2026-4000-8001-000000000015'::uuid,'e7301030-2026-4000-8001-000000000016'::uuid,'e7301030-2026-4000-8001-000000000017'::uuid,'e7301030-2026-4000-8001-000000000018'::uuid,'e7301030-2026-4000-8001-000000000019'::uuid,'e7301030-2026-4000-8001-000000000020'::uuid]) WHERE explanation IS NOT NULL OR options::text LIKE '%"correct"%') THEN RAISE EXCEPTION 'answer leakage'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements('[{"id":"e7301030-2026-4000-8003-000000000001","answer":"Estructural"},{"id":"e7301030-2026-4000-8003-000000000011","answer":"Escápula y clavícula"},{"id":"e7301030-2026-4000-8003-000000000021","answer":"Psoas mayor e ilíaco"},{"id":"e7301030-2026-4000-8003-000000000031","answer":"7"},{"id":"e7301030-2026-4000-8003-000000000041","answer":"Encéfalo y médula espinal"},{"id":"e7301030-2026-4000-8003-000000000051","answer":"El interior es más negativo respecto al exterior"},{"id":"e7301030-2026-4000-8003-000000000061","answer":"Detección del estímulo frente a su procesamiento e interpretación"},{"id":"e7301030-2026-4000-8003-000000000071","answer":"Retina"},{"id":"e7301030-2026-4000-8003-000000000081","answer":"Una neurona motora y las fibras musculares que inerva"},{"id":"e7301030-2026-4000-8003-000000000091","answer":"Temperatura es una variable de estado y calor es transferencia de energía"},{"id":"e7301030-2026-4000-8003-000000000101","answer":"Amperio"},{"id":"e7301030-2026-4000-8003-000000000111","answer":"Frecuencia"},{"id":"e7301030-2026-4000-8003-000000000121","answer":"M=F·d"},{"id":"e7301030-2026-4000-8003-000000000131","answer":"Fuerza dividida por área"},{"id":"e7301030-2026-4000-8003-000000000141","answer":"Cuántas veces se realiza la actividad"},{"id":"e7301030-2026-4000-8003-000000000151","answer":"Aumentar la carga demasiado rápido"},{"id":"e7301030-2026-4000-8003-000000000161","answer":"Fuerza muscular"},{"id":"e7301030-2026-4000-8003-000000000171","answer":"Where does it hurt?"},{"id":"e7301030-2026-4000-8003-000000000181","answer":"Elbow"},{"id":"e7301030-2026-4000-8003-000000000191","answer":"Ability"},{"id":"e7301030-2026-4000-8003-000000000008","answer":"Explicar el procedimiento y obtener aceptación"},{"id":"e7301030-2026-4000-8003-000000000155","answer":"Detener y buscar atención urgente"},{"id":"e7301030-2026-4000-8003-000000000165","answer":"Valorar la calidad y adaptar la tarea"}]'::jsonb) LOOP
 v:=public.submit_curriculum_topic_answer_v3((x->>'id')::uuid,jsonb_build_object('text',x->>'answer'));
 IF coalesce((v->>'correct')::boolean,false)<>true OR length(v->>'explanation')<20 THEN RAISE EXCEPTION 'Correct answer failed: % %',x,v; END IF;
 v:=public.submit_curriculum_topic_answer_v3((x->>'id')::uuid,jsonb_build_object('text','__respuesta_incorrecta_de_prueba__'));
 IF (v->>'correct')::boolean IS DISTINCT FROM false THEN RAISE EXCEPTION 'Wrong answer failed'; END IF;
 END LOOP;
END $$;
