idated"},{"id":"b7301030-2026-4000-8003-000000000036","options":[{"text":"Castigo negativo","correct":false},{"text":"Castigo positivo","correct":false},{"text":"Ausencia de aprendizaje","correct":false},{"text":"Refuerzo negativo","correct":true}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"b7301030-2026-4000-8001-000000000001","image_url":null,"created_at":"2026-10-30T20:14:14.575389+00:00","difficulty":2,"updated_at":"2026-10-30T20:14:14.575389+00:00","explanation":"Retirar un estímulo aversivo aumentando la conducta corresponde a refuerzo negativo.","is_published":true,"source_label":"Entrenamiento original · https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning","display_order":6,"question_text":"Se retira una consecuencia aversiva tras una conducta y esta aumenta. ¿Qué mecanismo es?","question_type":"clinical_case","accepted_answers":[],"validation_status":"source_validated"},{"id":"b7301030-2026-4000-8003-000000000037","options":[{"text":"Refuerzo positivo","correct":false},{"text":"Condicionamiento clásico necesariamente","correct":false},{"text":"Castigo negativo","correct":true},{"text":"Refuerzo negativo","correct":false}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"b7301030-2026-4000-8001-000000000001","image_url":null,"created_at":"2026-10-30T20:14:14.575389+00:00","difficulty":1,"updated_at":"2026-10-30T20:14:14.575389+00:00","explanation":"En esta clasificación, retirar es negativo y disminuir una conducta es castigo.","is_published":true,"source_label":"Entrenamiento original · https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning","display_order":7,"question_text":"Se retira una consecuencia agradable y la conducta disminuye. ¿Qué concepto corresponde?","question_type":"mcq","accepted_answers":[],"validation_status":"source_validated"},{"id":"b7301030-2026-4000-8003-000000000038","options":[{"text":"Confundir estímulos con respuestas","correct":false},{"text":"Reforzar aproximaciones sucesivas a una conducta objetivo","correct":true},{"text":"Exigir solo el resultado final desde el primer intento","correct":false},{"text":"Aplicar siempre un castigo físico","correct":false}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"b7301030-2026-4000-8001-000000000001","image_url":null,"created_at":"2026-10-30T20:14:14.575389+00:00","difficulty":1,"updated_at":"2026-10-30T20:14:14.575389+00:00","explanation":"El moldeamiento refuerza progresivamente respuestas cada vez más cercanas al objetivo.","is_published":true,"source_label":"Entrenamiento original · https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning","display_order":8,"question_text":"¿Qué describe el moldeamiento?","question_type":"mcq","accepted_answers":[],"validation_status":"source_validated"},{"id":"b7301030-2026-4000-8003-000000000039","options":[{"text":"La respuesta condicionada se adquiere mediante aprendizaje asociativo","correct":true},{"text":"La respuesta condicionada nunca depende del aprendizaje","correct":false},{"text":"Ambas palabras significan un estímulo externo","correct":false},{"text":"La respuesta incondicionada exige siempre entrenamiento","correct":false}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"b7301030-2026-4000-8001-000000000001","image_url":null,"created_at":"2026-10-30T20:14:14.575389+00:00","difficulty":1,"updated_at":"2026-10-30T20:14:14.575389+00:00","explanation":"La respuesta condicionada es aprendida; la incondicionada no necesita ese aprendizaje previo.","is_published":true,"source_label":"Entrenamiento original · https://openstax.org/books/psychology-2e/pages/6-2-classical-conditioning","display_order":9,"question_text":"¿Qué distingue una respuesta condicionada de una respuesta incondicionada?","question_type":"mcq","accepted_answers":[],"validation_status":"source_validated"},{"id":"b7301030-2026-4000-8003-000000000040","options":[{"text":"Toda felicitación es necesariamente un refuerzo eficaz","correct":false},{"text":"Se ha probado un castigo negativo","correct":false},{"text":"Se ha demostrado una lesión","correct":false},{"text":"No se ha demostrado que la felicitación funcione como refuerzo","correct":true}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"b7301030-2026-4000-8001-000000000001","image_url":null,"created_at":"2026-10-30T20:14:14.575389+00:00","difficulty":2,"updated_at":"2026-10-30T20:14:14.575389+00:00","explanation":"El refuerzo se identifica por su efecto sobre la conducta, no solo por la intención de quien lo ofrece.","is_published":true,"source_label":"Entrenamiento original · https://openstax.org/books/psychology-2e/pages/6-3-operant-conditioning","display_order":10,"question_text":"Un profesional añade una felicitación, pero la conducta no aumenta. ¿Qué puede concluirse con esos datos?","question_type":"clinical_case","accepted_answers":[],"validation_status":"source_validated"},{"id":"b7301030-2026-4000-8003-000000000041","options":[{"text":"Las condiciones de vivienda","correct":true},{"text":"La secuencia de una proteína aislada","correct":false},{"text":"El diámetro de una mitocondria","correct":false},{"text":"La forma de una válvula cardíaca","correct":false}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"b7301030-2026-4000-8001-000000000002","image_url":null,"created_at":"2026-10-30T20:14:14.575389+00:00","difficulty":1,"updated_at":"2026-10-30T20:14:14.575389+00:00","explanation":"La vivienda forma parte de las condiciones de vida que influyen en la salud.","is_published":true,"source_label":"Entrenamiento original · https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health","display_order":1,"question_text":"¿Cuál es un determinante social de la salud?","question_type":"mcq","accepted_answers":[],"validation_status":"source_validated"},{"id":"b7301030-2026-4000-8003-000000000042","options":[{"text":"Que solo existe diferencia entre dos grupos extremos","correct":false},{"text":"Que la salud depende exclusivamente de la genética","correct":false},{"text":"Que todas las personas tienen idénticas condiciones","correct":false},{"text":"Una relación progresiva entre desventaja social y peores resultados de salud","correct":true}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"b7301030-2026-4000-8001-000000000002","image_url":null,"created_at":"2026-10-30T20:14:14.575389+00:00","difficulty":1,"updated_at":"2026-10-30T20:14:14.575389+00:00","explanation":"La OMS describe una relación entre desventaja, ingresos, educación y salud a lo largo de la escala social.","is_published":true,"source_label":"Entrenamiento original · https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health","display_order":2,"question_text":"¿Qué expresa el gradiente social de la salud?","question_type":"mcq","accepted_answers":[],"validation_status":"source_validated"},{"id":"b7301030-2026-4000-8003-000000000043","options":[{"text":"La nacionalidad explica toda la conducta","correct":false},{"text":"La fisiología celular deja de ser relevante","correct":false},{"text":"Existen barreras sociales de acceso que deben explorarse","correct":true},{"text":"Se demuestra que no quiere recuperarse","correct":false}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"b7301030-2026-4000-8001-000000000002","image_url":null,"created_at":"2026-10-30T20:14:14.575389+00:00","difficulty":2,"updated_at":"2026-10-30T20:14:14.575389+00:00","explanation":"El trabajo y las condiciones de acceso pueden limitar la asistencia; no debe inferirse desinterés sin explorarlos.","is_published":true,"source_label":"Entrenamiento original · https://www.who.int/es/news-room/fact-sheets/detail/social-determinants-of-health","display_order":3,"question_text":"Una persona falta a sesiones por turnos laborales y falta de transporte. ¿Qué interpretación está mejor fundamentada?","question_type":"clinical_case","accepted_answers":[],"validation_status":"source_validated"},{"id":"b7301030-2026-4000-8003-000000000044","options":[{"text":"Solo los resultados d