30","academic_semester":1,"external_expert_review":"pending"},"topic_id":"c7301030-2026-4000-8001-000000000006","image_url":null,"created_at":"2026-10-30T20:23:07.961805+00:00","difficulty":1,"updated_at":"2026-10-30T20:23:07.961805+00:00","explanation":"Acordar prioridades facilita una conversación centrada en lo que importa a la persona.","is_published":true,"source_label":"Entrenamiento original · https://www.nice.org.uk/guidance/ng197/chapter/Recommendations","display_order":1,"question_text":"¿Qué pregunta ayuda a acordar las prioridades al iniciar la conversación?","question_type":"mcq","accepted_answers":[],"validation_status":"source_validated"},{"id":"c7301030-2026-4000-8003-000000000052","options":[{"text":"Dar todas las instrucciones al final sin preguntas","correct":false},{"text":"Utilizar solo terminología técnica","correct":false},{"text":"Repetir más rápido si aparece una duda","correct":false},{"text":"Dar información manejable y verificar comprensión antes de continuar","correct":true}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://www.nice.org.uk/guidance/ng197/chapter/Recommendations"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-suite-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"c7301030-2026-4000-8001-000000000006","image_url":null,"created_at":"2026-10-30T20:23:07.961805+00:00","difficulty":1,"updated_at":"2026-10-30T20:23:07.961805+00:00","explanation":"NICE recomienda dividir la información en unidades y comprobar lo comprendido.","is_published":true,"source_label":"Entrenamiento original · https://www.nice.org.uk/guidance/ng197/chapter/Recommendations","display_order":2,"question_text":"¿Qué describe la técnica de explicar por partes y comprobar?","question_type":"mcq","accepted_answers":[],"validation_status":"source_validated"},{"id":"c7301030-2026-4000-8003-000000000053","options":[{"text":"Repita exactamente cada término técnico","correct":false