43","options":[{"text":"Solo el nombre del diagnóstico","correct":false},{"text":"Solo una prueba de imagen","correct":false},{"text":"Autocuidados, redes de apoyo y distintos servicios o prácticas","correct":true},{"text":"Solo la última consulta","correct":false}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://www.who.int/about/governance/constitution","https://www.who.int/health-topics/traditional-complementary-and-integrative-medicine"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-final-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"d7301030-2026-4000-8001-000000000015","image_url":null,"created_at":"2026-10-30T20:40:10.013424+00:00","difficulty":1,"updated_at":"2026-10-30T20:40:10.013424+00:00","explanation":"El recorrido de atención puede incluir recursos formales e informales utilizados en distintos momentos.","is_published":true,"source_label":"Entrenamiento original · https://www.who.int/about/governance/constitution · https://www.who.int/health-topics/traditional-complementary-and-integrative-medicine","display_order":3,"question_text":"¿Qué puede incluir un itinerario de atención?","question_type":"mcq","accepted_answers":[],"validation_status":"source_validated"},{"id":"d7301030-2026-4000-8003-000000000144","options":[{"text":"¿Acepta que no escuchemos sus expectativas?","correct":false},{"text":"¿Qué ha probado hasta ahora y qué esperaba conseguir?","correct":true},{"text":"¿Podemos omitir todo lo que ha hecho?","correct":false},{"text":"¿Su origen explica ya todas sus decisiones?","correct":false}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://www.who.int/about/governance/constitution","https://www.who.int/health-topics/traditional-complementary-and-integrative-medicine"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-final-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"d73010