":"pending"},"topic_id":"d7301030-2026-4000-8001-000000000015","image_url":null,"created_at":"2026-10-30T20:40:10.013424+00:00","difficulty":1,"updated_at":"2026-10-30T20:40:10.013424+00:00","explanation":"La OMS sitúa evidencia y seguridad entre los requisitos de una integración responsable.","is_published":true,"source_label":"Entrenamiento original · https://www.who.int/about/governance/constitution · https://www.who.int/health-topics/traditional-complementary-and-integrative-medicine","display_order":7,"question_text":"¿Qué debe acompañar una integración responsable de prácticas?","question_type":"mcq","accepted_answers":[],"validation_status":"source_validated"},{"id":"d7301030-2026-4000-8003-000000000148","options":[{"text":"Que la seguridad importa","correct":false},{"text":"Que natural demuestra seguridad y eficacia","correct":true},{"text":"Que conviene preguntar qué utiliza","correct":false},{"text":"Que deben explorarse expectativas","correct":false}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://www.who.int/about/governance/constitution","https://www.who.int/health-topics/traditional-complementary-and-integrative-medicine"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-final-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"d7301030-2026-4000-8001-000000000015","image_url":null,"created_at":"2026-10-30T20:40:10.013424+00:00","difficulty":2,"updated_at":"2026-10-30T20:40:10.013424+00:00","explanation":"El origen natural de un producto no basta para probar su seguridad o eficacia.","is_published":true,"source_label":"Entrenamiento original · https://www.who.int/about/governance/constitution · https://www.who.int/health-topics/traditional-complementary-and-integrative-medicine","display_order":8,"question_text":"Una persona usa un producto porque es natural. ¿Qué inferencia debe evitarse?","question_type":"clinical_case","accepted_answers":[],"validation_status":"source_v