ipos generales de tejido muscular?","question_type":"mcq","accepted_answers":[],"validation_status":"source_validated"},{"id":"b7301030-2026-4000-8003-000000000006","options":[{"text":"Serosa","correct":false},{"text":"Sinovial","correct":false},{"text":"Membrana nuclear","correct":false},{"text":"Mucosa","correct":true}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"d7301030-2026-4000-8001-000000000101","image_url":null,"created_at":"2026-10-30T20:14:14.575389+00:00","difficulty":1,"updated_at":"2026-10-30T20:40:10.013424+00:00","explanation":"Las mucosas revisten vías abiertas al exterior; las serosas se relacionan con cavidades cerradas.","is_published":true,"source_label":"Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues","display_order":6,"question_text":"¿Qué membrana reviste un conducto que comunica con el exterior, como el tubo digestivo?","question_type":"mcq","accepted_answers":[],"validation_status":"source_validated"},{"id":"b7301030-2026-4000-8003-000000000007","options":[{"text":"Pericardio","correct":false},{"text":"Membrana sinovial","correct":false},{"text":"Pleura","correct":true},{"text":"Peritoneo","correct":false}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/4-1-types-of-tissues"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"d7301030-2026-4000-8001-000000000101","image_url":null,"created_at":"2026-10-30T20:14:14.575389+00:00","difficulty":1,"updated_at":"2026-10-30T20:40:10.013424+00:00","explanation":"La pleura recubre los pulmones y reviste su cavid