re dos zonas","correct":true}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"d7301030-2026-4000-8001-000000000102","image_url":null,"created_at":"2026-10-30T20:14:14.575389+00:00","difficulty":1,"updated_at":"2026-10-30T20:40:10.013424+00:00","explanation":"Un gradiente expresa una diferencia de concentración que puede impulsar transporte pasivo.","is_published":true,"source_label":"Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane","display_order":6,"question_text":"¿Qué significa gradiente de concentración?","question_type":"mcq","accepted_answers":[],"validation_status":"source_validated"},{"id":"b7301030-2026-4000-8003-000000000017","options":[{"text":"Ocurre sin ninguna proteína","correct":false},{"text":"Mueve obligatoriamente sustancias contra su gradiente","correct":false},{"text":"Utiliza proteínas sin requerir ATP directamente para impulsar el paso","correct":true},{"text":"Siempre consume ATP en el transportador","correct":false}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"d7301030-2026-4000-8001-000000000102","image_url":null,"created_at":"2026-10-30T20:14:14.575389+00:00","difficulty":1,"updated_at":"2026-10-30T20:40:10.013424+00:00","explanation":"La difusión facilitada es un mecanismo pasivo mediado por proteínas.","is_published":true,"source_label":"Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane","display_order":7,"question_text":"¿Cuál de estas afirmaciones sobre difusión facilitada es correcta?","question_type":"mcq","accepted_answers":[],"validation_status":"source_validated"},{"id":"b7301030-2026-4000-8003-000000000018","options":[{"text":"No puede moverse en ninguna dirección","correct":false},{"text":"Hacia el lado con mayor concentración de ese soluto","correct":true},{"text":"Hacia el lado con menor concentración de ese soluto","correct":false},{"text":"Siempre hacia la izquierda","correct":false}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1-20261030","academic_semester":1,"external_expert_review":"pending"},"topic_id":"d7301030-2026-4000-8001-000000000102","image_url":null,"created_at":"2026-10-30T20:14:14.575389+00:00","difficulty":2,"updated_at":"2026-10-30T20:40:10.013424+00:00","explanation":"La diferencia de solutos no permeantes genera movimiento osmótico neto de agua hacia el medio más concentrado.","is_published":true,"source_label":"Entrenamiento original · https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane","display_order":8,"question_text":"Dos compartimentos contienen distintas concentraciones de un soluto impermeante. Si solo el agua puede cruzar, ¿hacia qué lado se moverá netamente, en condiciones comparables?","question_type":"clinical_case","accepted_answers":[],"validation_status":"source_validated"},{"id":"b7301030-2026-4000-8003-000000000019","options":[{"text":"Colesterol","correct":true},{"text":"Colágeno extracelular únicamente","correct":false},{"text":"Hemoglobina circulante","correct":false},{"text":"ADN nuclear","correct":false}],"metadata":{"origin":"original_training","language":"es","source_urls":["https://openstax.org/books/anatomy-and-physiology-2e/pages/3-1-the-cell-membrane"],"verified_at":"2026-10-30","academic_year":1,"content_batch":"es-s1