UPDATE public.curriculum_quiz_questions SET question_text='Un patient a du mal à se lever d’une chaise et à marcher. À quel domaine cela se rattache-t-il le plus directement ?',options='[{"text":"Mobilité fonctionnelle","correct":true},{"text":"Vision","correct":false},{"text":"Audition","correct":false},{"text":"Fonction digestive","correct":false}]'::jsonb,explanation='Ces difficultés relèvent de la mobilité fonctionnelle.',metadata='{"difficulty_scale_version":"2026-10-v1"}'::jsonb,updated_at=now() WHERE id='bda22062-f574-409f-a811-29cae9b8c6b8'::uuid AND metadata->>'language_revision'='es-s2-20261030' AND question_text='Caso — La persona tiene dificultad para levantarse y caminar. ¿Qué ámbito funcional se describe?' AND options='[{"text":"Movilidad funcional","correct":true},{"text":"Visión","correct":false},{"text":"Audición","correct":false},{"text":"Función digestiva","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Que signifie « actividades de la vida diaria » ?',options='[{"text":"Activités de la vie quotidienne","correct":true},{"text":"Activités sportives de haut niveau","correct":false},{"text":"Examens radiologiques","correct":false},{"text":"Traitements médicamenteux","correct":false}]'::jsonb,explanation='Cette expression correspond aux activités de la vie quotidienne.',metadata='{"difficulty_scale_version":"2026-10-v1"}'::jsonb,updated_at=now() WHERE id='8edbde12-7c91-4fcc-adb7-0307d796e4b4'::uuid AND metadata->>'language_revision'='es-s2-20261030' AND question_text='Vocabulario FR/ES — ¿Cómo se traduce «actividades de la vida diaria» al francés?' AND options='[{"text":"Activités de la vie quotidienne","correct":true},{"text":"Activités sportives de haut niveau","correct":false},{"text":"Examens radiologiques","correct":false},{"text":"Traitements médicamenteux","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Quel signe pendant un exercice impose de s’arrêter selon MedlinePlus ?',options='[{"text":"Vertiges","correct":true},{"text":"Respiration calme","correct":false},{"text":"Bonne tolérance","correct":false},{"text":"Confort stable","correct":false}]'::jsonb,explanation='Douleur, vertiges ou problème respiratoire doivent conduire à arrêter et en parler au professionnel.',metadata='{"difficulty_scale_version":"2026-10-v1"}'::jsonb,updated_at=now() WHERE id='900bb562-a71e-488d-9983-a3bcbe57b7b7'::uuid AND metadata->>'language_revision'='es-s2-20261030' AND question_text='¿Qué síntoma durante el ejercicio exige detener y reevaluar?' AND options='[{"text":"Mareos","correct":true},{"text":"Respiración tranquila","correct":false},{"text":"Buena tolerancia","correct":false},{"text":"Comodidad estable","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Quelle aide peut être envisagée si la marche est difficile ?',options='[{"text":"Une aide à la marche","correct":true},{"text":"Un repos au lit systématique","correct":false},{"text":"Aucune adaptation","correct":false},{"text":"Un exercice douloureux imposé","correct":false}]'::jsonb,explanation='Une canne ou un déambulateur peut être envisagé selon la situation.',metadata='{"difficulty_scale_version":"2026-10-v1"}'::jsonb,updated_at=now() WHERE id='257fb664-2fb2-4b5a-97e1-009ab8e0cbee'::uuid AND metadata->>'language_revision'='es-s2-20261030' AND question_text='¿Qué recurso puede valorarse cuando caminar resulta difícil?' AND options='[{"text":"Una ayuda para caminar","correct":true},{"text":"Reposo sistemático en cama","correct":false},{"text":"Ninguna adaptación","correct":false},{"text":"Ejercicio doloroso impuesto","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Que signifie « riesgo de caída » en français ?',options='[{"text":"Risque de chute","correct":true},{"text":"Risque infectieux","correct":false},{"text":"Douleur musculaire","correct":false},{"text":"Amplitude articulaire","correct":false}]'::jsonb,explanation='Riesgo de caída signifie risque de chute.',metadata='{"difficulty_scale_version":"2026-10-v1"}'::jsonb,updated_at=now() WHERE id='e6fa92e4-fa8b-4635-b973-b523a04dc3da'::uuid AND metadata->>'language_revision'='es-s2-20261030' AND question_text='Vocabulario FR/ES — ¿Cuál es la traducción francesa de «riesgo de caída»?' AND options='[{"text":"Risque de chute","correct":true},{"text":"Risque infectieux","correct":false},{"text":"Douleur musculaire","correct":false},{"text":"Amplitude articulaire","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Dans une observation fonctionnelle simple, que peut-on regarder en priorité ?',options='[{"text":"Marche, équilibre et coordination","correct":true},{"text":"Uniquement la couleur des vêtements","correct":false},{"text":"Uniquement la taille","correct":false},{"text":"Uniquement le poids du sac","correct":false}]'::jsonb,explanation='La marche, l’équilibre et la coordination font partie des éléments utiles à observer.',metadata='{"difficulty_scale_version":"2026-10-v1"}'::jsonb,updated_at=now() WHERE id='df2ebf0e-1d07-4b6c-9109-6a1457841ec4'::uuid AND metadata->>'language_revision'='es-s2-20261030' AND question_text='¿Qué puede observarse en una valoración funcional básica?' AND options='[{"text":"Marcha, equilibrio y coordinación","correct":true},{"text":"Solo el color de la ropa","correct":false},{"text":"Solo la talla","correct":false},{"text":"Solo el peso de la mochila","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Lors d’une évaluation fonctionnelle simple de l’épaule, que peut-on observer ?',options='[{"text":"Le mouvement de l’épaule et de l’omoplate","correct":true},{"text":"Uniquement la température corporelle","correct":false},{"text":"Uniquement la vision","correct":false},{"text":"Uniquement le pouls radial","correct":false}]'::jsonb,explanation='MedlinePlus propose notamment d’observer le mouvement de l’épaule et de l’omoplate.',metadata='{"difficulty_scale_version":"2026-10-v1"}'::jsonb,updated_at=now() WHERE id='848f0846-6c22-4fe5-be5a-c614a9d5eb5b'::uuid AND metadata->>'language_revision'='es-s2-20261030' AND question_text='¿Qué movimientos es pertinente observar al valorar funcionalmente el hombro?' AND options='[{"text":"Movimiento del hombro y de la escápula","correct":true},{"text":"Solo temperatura corporal","correct":false},{"text":"Solo visión","correct":false},{"text":"Solo pulso radial","correct":false}]'::jsonb;
UPDATE public.curriculum_quiz_questions SET question_text='Un patient a douleur, faiblesse et raideur de l’épaule. Quelle évaluation est pertinente ?',options='[{"text":"Rango de movimiento + músculos débiles o rígidos + movimientos dolorosos","correct":true},{"text":"Uniquement la taille du patient","correct":false},{"text":"Uniquement la tension artérielle","correct":false},{"text":"Uniquement la couleur de peau","correct":false}]'::jsonb,explanation='L’amplitude, la faiblesse/raideur musculaire et les mouvements aggravants font partie des éléments fonctionnels décrits.',metadata='{"difficulty_scale_version":"2026-10-v1"}'::jsonb,updated_at=now() WHERE id='4b8011ac-4244-47da-a9e7-5f9c30c989a7'::uuid AND metadata->>'language_revision'='es-s2-20261030' AND question_text='Caso — Hay dolor, debilidad y rigidez de hombro. ¿Qué dominios de valoración son pertinentes?' AND options='[{"text":"Rango de movimiento + músculos débiles o rígidos + movimientos dolorosos","correct":true},{"text":"Solo talla de la persona","correct":false},{"text":"Solo presión arterial","correct":false},{"text":"Solo color de piel","correct":false}]'::jsonb;
